// ---------- "INSTALL AS APP" PROMPT ----------
let deferredInstallPrompt = null;
let awaitingInstallPromptForLogin = false;
window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  deferredInstallPrompt = e;
  // Chrome can fire this well after page load (engagement heuristics), so if
  // we already tried and failed to show the banner right after login, retry
  // now that the browser has actually made the prompt available.
  if (awaitingInstallPromptForLogin) maybeShowInstallPrompt();
});
function isStandalone() {
  return window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
}
function isIos() {
  return /iPhone|iPad|iPod/.test(navigator.userAgent) && !window.MSStream;
}
function maybeShowInstallPrompt() {
  if (isStandalone()) return;
  if (localStorage.getItem("medris-install-dismissed")) return;
  const modal = byId("installPromptModal");
  if (!modal || !modal.classList.contains("hidden")) return;
  // Same reasoning as the banner's own check on this modal: never show both
  // at once, they'd just be two separate ways to ask for the same tap.
  if (byId("levroInstallBanner")?.classList.contains("is-visible")) return;
  if (deferredInstallPrompt) {
    byId("installModalActionBtn").classList.remove("hidden");
    byId("installModalIosMsg").classList.add("hidden");
  } else if (isIos()) {
    byId("installModalActionBtn").classList.add("hidden");
    byId("installModalIosMsg").classList.remove("hidden");
  } else {
    return; // not installable and no manual instructions to give
  }
  modal.classList.remove("hidden");
  trackModalOpened("installPromptModal");
}
async function runInstallPrompt() {
  if (!deferredInstallPrompt) return;
  deferredInstallPrompt.prompt();
  await deferredInstallPrompt.userChoice;
  deferredInstallPrompt = null;
  dismissInstallPrompt();
}
function dismissInstallPrompt() {
  byId("installPromptModal")?.classList.add("hidden");
  localStorage.setItem("medris-install-dismissed", "1");
  if (dismissibleModalId === "installPromptModal") dismissibleModalId = null;
  setTimeout(maybeShowNotifPrompt, 400);
}

// ---------- PUSH NOTIFICATIONS (on top of email, not instead of) ----------
// Public VAPID key - safe to expose client-side, same reasoning as the
// Supabase anon key above. The matching private key lives only in Vercel
// (VAPID_PRIVATE_KEY), used by api/notify-push.js to actually send.
const VAPID_PUBLIC_KEY = "BJ7h-JVsXaOpYXY5st5L7esSDOPjhRROincFPTT013a1ZY3U62WIKPAoFEDzBgFB8g3H2DBNX1iRw8GzdPWR88k";

function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const rawData = atob(base64);
  return Uint8Array.from([...rawData].map((c) => c.charCodeAt(0)));
}
function pushSupported() {
  return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;
}
function maybeShowNotifPrompt() {
  if (!session || !pushSupported()) return;
  if (Notification.permission === "granted") { byId("notifPromptModal")?.classList.add("hidden"); return; }
  // Asked again every time the app is opened or someone logs in, until notifications are on. Once they are on, never again.
  const stamp = String(session.user?.id || "");
  if (window.__notifPromptShownFor === stamp) return;
  const installModal = byId("installPromptModal");
  if (installModal && !installModal.classList.contains("hidden")) return;
  const prompt = byId("notifPromptModal");
  if (!prompt) return;
  const btn = prompt.querySelector(".install-modal-actions .btn:not(.btn-outline)");
  const body = prompt.querySelector("p");
  if (Notification.permission === "denied") {
    if (body) body.textContent = "Notifications are blocked for Levromart. Open your browser/site settings to allow them.";
    if (btn) { btn.textContent = "Open notification settings"; btn.onclick = () => { showToast("Open your browser's site settings and allow notifications for Levromart, then try again.", "info"); }; }
  }
  window.__notifPromptShownFor = stamp;
  prompt.classList.remove("hidden");
  trackModalOpened("notifPromptModal");
}
function dismissNotifPrompt() {
  byId("notifPromptModal")?.classList.add("hidden");
  localStorage.setItem("medris-notif-dismissed", "1");
  if (dismissibleModalId === "notifPromptModal") dismissibleModalId = null;
  setTimeout(maybeShowTour, 400);
}
async function syncPushSubscription(registration) {
  if (!session || !pushSupported()) return null;
  const reg = registration || await navigator.serviceWorker.ready;
  let sub = await reg.pushManager.getSubscription();
  if (!sub) return null;
  const raw = sub.toJSON();
  if (!raw.endpoint || !raw.keys?.p256dh || !raw.keys?.auth) return null;
  const { error } = await sb.from("push_subscriptions").upsert(
    { user_id: session.user.id, endpoint: raw.endpoint, p256dh: raw.keys.p256dh, auth_key: raw.keys.auth },
    { onConflict: "endpoint" }
  );
  if (error) throw error;
  return sub;
}

async function refreshPushSubscription() {
  if (!session || !pushSupported() || Notification.permission !== "granted") return null;
  try {
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    // Permission is on but the browser dropped the subscription (Android does this after
    // updates, cleared data or long idle): quietly subscribe again so pushes keep arriving.
    if (!sub && !(isIos() && !isStandalone())) {
      try { sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY) }); } catch (_) { return null; }
    }
    if (!sub) return null;
    await syncPushSubscription(reg);
    return sub;
  } catch (_) {
    return null;
  }
}
// ---------- Call & message alerts check (Settings) ----------
async function levroPushStatus() {
  if (!pushSupported()) return { ok: false, text: "This browser can't receive alerts when the app is closed." };
  if (Notification.permission === "denied") return { ok: false, text: "Alerts are blocked for Levromart. Allow notifications in your browser's site settings, then tap the button." };
  if (Notification.permission !== "granted") return { ok: false, text: "Alerts are off. Tap the button to turn them on." };
  try {
    const reg = await navigator.serviceWorker.ready;
    const sub = await reg.pushManager.getSubscription();
    return sub ? { ok: true, text: "Alerts are on for this phone." } : { ok: false, text: "Alerts are allowed but this phone isn't registered yet. Tap the button to fix it." };
  } catch (_) { return { ok: false, text: "Couldn't check alerts on this phone." }; }
}
async function levroTestPush(btn) {
  if (!session) { showLogin(); return; }
  if (!pushSupported()) { showToast("This browser can't receive alerts when the app is closed.", "error"); return; }
  const label = btn?.innerHTML; if (btn) { btn.disabled = true; btn.textContent = "Working…"; }
  try {
    if (Notification.permission !== "granted") {
      const perm = await Notification.requestPermission();
      if (perm !== "granted") { showToast("Alerts are blocked. Allow notifications in your browser's site settings.", "info"); return; }
    }
    if (isIos() && !isStandalone()) { showToast("On iPhone, add Levromart to your Home Screen first.", "info"); return; }
    const reg = await navigator.serviceWorker.ready;
    // Start from a fresh registration so a stale one can't swallow the alert.
    const old = await reg.pushManager.getSubscription();
    if (old) { try { await old.unsubscribe(); } catch (_) {} }
    await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY) });
    await syncPushSubscription(reg);
    const { data: { session: fresh } } = await sb.auth.getSession();
    const res = await fetch("/api/notify", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "test-push", accessToken: fresh?.access_token || session.access_token }) });
    const out = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(out.error || "The test could not be sent.");
    const n = out.sent || 0;
    showToast(n ? `Test alert sent to ${n} device${n === 1 ? "" : "s"}. Lock your phone and wait a few seconds.` : "No device accepted the alert. Open Settings on this phone and try again.", n ? "success" : "error");
  } catch (err) {
    showToast(err?.message || "Couldn't run the check.", "error");
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = label; }
    levroPaintPushStatus();
  }
}
async function levroPaintPushStatus() {
  const el = byId("pushCheckStatus"); if (!el) return;
  const st = await levroPushStatus();
  el.textContent = st.text; el.classList.toggle("push-ok", st.ok);
}
async function enablePushNotifications() {
  if (!pushSupported()) { showToast("Push notifications are not supported on this browser.", "error"); return; }
  try {
    const permission = await Notification.requestPermission();
    if (permission !== "granted") {
      byId("notifPromptModal")?.classList.add("hidden");
      try { localStorage.setItem("levromart-notif-prompt-v2", JSON.stringify({ deniedUntil: Date.now() + 24*60*60*1000 })); } catch (_) {}
      if (permission === "denied") showToast("Notifications are blocked. Allow them from your browser/site settings when ready.", "info");
      return;
    }
    if (isIos() && !isStandalone()) {
      showToast("On iPhone, add Levromart to your Home Screen first, then turn notifications on.", "info");
      return;
    }
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if (!sub) sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY) });
    await syncPushSubscription(reg);
    try { localStorage.removeItem("levromart-notif-prompt-v2"); localStorage.removeItem("medris-notif-dismissed"); } catch (_) {}
    byId("notifPromptModal")?.classList.add("hidden");
    if (dismissibleModalId === "notifPromptModal") dismissibleModalId = null;
    showToast("Notifications turned on.", "success");
  } catch (err) {
    showToast(err?.message || "Couldn't turn on notifications on this device.", "error");
  }
}

// ---------- FIRST-VISIT APP TOUR (live - walks the real pages, spotlights real elements) ----------
