async function handleNotifItemClick(event, id) {
  if (event) { event.preventDefault(); event.stopPropagation(); }
  const clicked = event?.currentTarget;
  if (clicked?.dataset.longPressConsumed === '1') { delete clicked.dataset.longPressConsumed; return; }
  if (notifSelectMode) {
    toggleNotifSelect(String(id));
    return;
  }
  const item = event?.currentTarget || getNotifHost()?.querySelector(`.notif-item[data-id="${CSS.escape(String(id))}"]`);
  if (!item) return;
  let params = {};
  try { params = JSON.parse(item.dataset.params || "{}"); } catch (_) {}
  await queueNotificationRead(id);
  closeAllPanels();
  if ((item.dataset.view || "home") === "messages" && params?.conversationId) {
    const conversationId = String(params.conversationId);
    // Refresh the inbox snapshot first so the destination always has the
    // exact conversation and its latest messages, even after a cold start or
    // when the notification was generated while the inbox list was stale.
    try { await refreshConversationInboxInBackground(); } catch (_) {}
    try {
      const {data:latestMessagesDesc}=await sb.from('messages').select('*').eq('conversation_id',conversationId).order('created_at',{ascending:false}).limit(200);
      const latestMessages=Array.isArray(latestMessagesDesc)?latestMessagesDesc.slice().reverse():latestMessagesDesc;
      if(Array.isArray(latestMessages)) lastSeenMessagesByConv.set(conversationId,latestMessages);
    } catch (_) {}
    navigate('messages',{conversationId});
    return;
  }
  navigate(item.dataset.view || 'home', params);
}

function switchNotifView(mode) {
  const allowed = new Set(["all","personal","orders","myListings","vendors"]);
  if (!allowed.has(mode)) mode = "all";
  if (mode === "myListings" && !vendor?.id) mode = "personal";
  notifViewMode = mode;
  exitNotifSelectMode(false);
  renderNotifPanel({ reuse: true });
}

function enterNotifSelectMode(id) {
  notifSelectMode = true;
  notifSelectedIds = id ? new Set([String(id)]) : new Set();
  renderNotifPanel();
}

function toggleNotifSelect(id) {
  if (!notifSelectMode) return;
  id = String(id);
  if (notifSelectedIds.has(id)) notifSelectedIds.delete(id);
  else notifSelectedIds.add(id);
  if (notifSelectedIds.size === 0) {
    exitNotifSelectMode();
    return;
  }
  const panel = getNotifHost();
  panel?.querySelectorAll(".notif-item").forEach((row) => {
    const selected = notifSelectedIds.has(String(row.dataset.id));
    row.classList.toggle("selected", selected);
    row.setAttribute("aria-selected", selected ? "true" : "false");
    row.querySelector(".notif-select-check")?.classList.toggle("active", selected);
  });
  const bar = panel?.querySelector(".notif-select-bar");
  const count = bar?.querySelector("strong");
  if (count) count.textContent = `${notifSelectedIds.size} selected`;
  const allVisible = getVisibleNotifIds().length > 0 && getVisibleNotifIds().every((x) => notifSelectedIds.has(String(x)));
  const selectAllBtn = bar?.querySelector("button[aria-label=\"Select all\"], button[aria-label=\"Deselect all\"]");
  if (selectAllBtn) {
    selectAllBtn.setAttribute("aria-label", allVisible ? "Deselect all" : "Select all");
    selectAllBtn.title = allVisible ? "Deselect all" : "Select all";
    const icon = selectAllBtn.querySelector("i");
    if (icon) icon.className = `fa-solid ${allVisible ? "fa-square-minus" : "fa-square-check"}`;
  }
  updateNotifSelectionActions();
}

// Tap outside the selected rows (or use browser back) to cancel batch selection.
// Toolbar controls remain interactive and are excluded from this dismissal.
function clearBatchSelectionOnOutsideTap(e) {
  const t = e?.target;
  if (!t || !msgSelectMode && !notifSelectMode) return;
  if (t.closest?.(".conv-list-item, .notif-item, .messages-selection-toolbar, .notif-select-bar")) return;
  if (t.closest?.(".modal, .drawer, .ai-chat-panel, input, textarea, select")) return;
  if (msgSelectMode) { msgSelectMode = false; msgSelectedIds.clear(); filterMsgList(); updateMsgSelectionBar(); }
  if (notifSelectMode) { notifSelectMode = false; notifSelectedIds.clear(); renderNotifPanel(); }
}
document.addEventListener("click", clearBatchSelectionOnOutsideTap);

function updateNotifSelectionActions() {
  const bar = getNotifHost()?.querySelector(".notif-select-bar");
  if (!bar) return;
  const hasSelection = notifSelectedIds.size > 0;
  bar.querySelectorAll(".notif-selection-action").forEach((btn) => {
    btn.disabled = !hasSelection;
    btn.setAttribute("aria-disabled", hasSelection ? "false" : "true");
  });
}

function getVisibleNotifIds() {
  return (window.__notifPanelIds || []).map(String);
}
function toggleSelectAllNotifs() {
  const allIds = getVisibleNotifIds();
  if (!allIds.length) return;
  const allSelected = allIds.every((id) => notifSelectedIds.has(String(id)));
  notifSelectMode = true;
  notifSelectedIds = allSelected ? new Set() : new Set(allIds.map(String));
  if (notifSelectedIds.size === 0) {
    exitNotifSelectMode();
    return;
  }
  renderNotifPanel();
}
function exitNotifSelectMode(rerender = true) {
  notifSelectMode = false;
  notifSelectedIds.clear();
  if (rerender) renderNotifPanel();
}

async function batchMarkNotifsRead(read) {
  const ids = [...notifSelectedIds].map(String);
  if (!ids.length) { showToast("Select at least one notification first.", "info"); return; }
  notifRenderEpoch++;
  const panel = getNotifHost();
  const rows = ids.map((id) => panel?.querySelector(`.notif-item[data-id="${CSS.escape(String(id))}"]`)).filter(Boolean);
  const oldUnread = new Map(rows.map((row) => [String(row.dataset.id), row.classList.contains("unread")]));
  rows.forEach((row) => { row.classList.toggle("unread", !read); row.classList.remove("selected"); row.setAttribute("aria-selected", "false"); });
  const count = ids.length;
  exitNotifSelectMode(false);
  showToast(`${count} notification${count === 1 ? "" : "s"} marked ${read ? "read" : "unread"}.`, "success");
  const { error } = await sb.from("notifications").update({ read }).in("id", ids);
  if (error) {
    oldUnread.forEach((wasUnread, id) => panel?.querySelector(`.notif-item[data-id="${CSS.escape(String(id))}"]`)?.classList.toggle("unread", wasUnread));
    renderNotifPanel();
    showToast(error.message || "Couldn't update notifications.", "error");
  } else {
    refreshNotifications(false).catch(() => {});
  }
}





let markAllNotifsBusy=false;
async function markSingleNotifRead(id) { return queueNotificationRead(id); }

let notifChannelUserId=null;
function subscribeNotifications() {
  const userId=session?.user?.id||null;if(notifChannel&&notifChannelUserId===userId)return;notifChannelUserId=userId;
  if (notifChannel) { sb.removeChannel(notifChannel); notifChannel = null; }
  if (!session) return;
  notifChannel = sb.channel(`notifications-${session.user.id}`)
    .on("postgres_changes", { event: "INSERT", schema: "public", table: "notifications", filter: `user_id=eq.${session.user.id}` }, (payload) => {
      // A new-message notification for the chat that is already open on screen:
      // no pop-up, no sound (like WhatsApp) -- just pull the message into the
      // thread right away and quietly mark the notification as read.
      const nParams = payload.new.target_params || {};
      window.__convRawAt = 0;
      window.__ordCnt = null;
      if (String(payload.new.type || "") === "incoming_call") {
        try { window.__levroIncomingCall?.(payload.new); } catch (_) {}
        refreshNotifications(false);
        return;
      }
      if (String(payload.new.type || "") === "new_message" && currentView === "messages" && !document.hidden
          && activeConversationId && String(nParams.conversationId || "") === String(activeConversationId)) {
        try { window.__levroReconcileChatNow?.(); } catch (_) {}
        Promise.resolve(sb.from("notifications").update({ read: true }).eq("id", payload.new.id)).catch(() => {});
        refreshNotifications(false);
        return;
      }
      playNotificationSound(payload.new);
      try { if (!document.hidden) navigator.vibrate?.([150, 80, 150]); } catch (_) {}
      showToast(payload.new.title, "info");
      refreshNotifications();
      // An order was just completed: ask for the review right away.
      if (String(payload.new.type || "") === "order_status_changed") setTimeout(() => { try { window.maybePromptLevromartReview?.(true); } catch (_) {} }, 1500);
      // Vendor approval/rejection and admin promotion/demotion change the
      // account's authoritative role. Refresh it immediately so the user does
      // not have to close/reopen the app before navigation and permissions
      // reflect the new state.
      const roleChangingTypes = new Set(["vendor_approved", "vendor_rejected", "vendor_deleted", "promoted_admin", "demoted_admin"]);
      if (roleChangingTypes.has(String(payload.new.type || ""))) {
        refreshAuthState().then(() => {
          if (currentView === "vendorApply" && profile?.role === "vendor") navigate("vendorDashboard", {}, false);
          else if (["vendorDashboard", "vendorProducts", "vendorOrders", "vendorEditProfile", "vendorSuggestionsInbox"].includes(currentView) && profile?.role !== "vendor") navigate("home", {}, false);
        }).catch((e) => console.warn("[Levromart] Role-change refresh failed:", e));
      }
    })
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'notifications',filter:`user_id=eq.${session.user.id}`},()=>refreshNotifications().catch(err=>console.warn('Notification refresh failed',err)))
    .subscribe(status=>{window.__notificationRealtimeStatus=status;if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')console.warn('Notification realtime unavailable',status);});
}
// Mobile browsers commonly suspend a backgrounded tab's websocket, and
// Postgres-changes realtime has no history to replay on reconnect -- any
// notification that arrived while the app was backgrounded is just gone
// from the live channel's point of view. That's why a notification could
// sit unseen until the person happened to open the notifications page
// (which does its own fresh fetch) instead of showing up the moment it
// was created. Catch up with a real fetch, and force a fresh channel
// (the stale one may still look "connected" while actually dead), every
// time the app comes back to the foreground.
document.addEventListener('visibilitychange',()=>{
  if(document.hidden||!session)return;
  refreshNotifications(false).catch(()=>{});
  notifChannelUserId=null;
  subscribeNotifications();
},{passive:true});

function invalidateMarketplaceState(){
  routeHtmlCache.clear();window.__homeBrowseCatalog=[];window.__allHomePackages=[];window.__homePackages=[];
  try{localStorage.removeItem(OFFLINE_HOME_CACHE_KEY);}catch(err){console.warn('Marketplace cache invalidation failed',err);}
}
let marketplaceLiveChannel=null,marketplaceLiveUser=null,marketplaceRefreshBusy=false,marketplaceRefreshAgain=false;
async function refreshMarketplaceRegions(){
  if(marketplaceRefreshBusy){marketplaceRefreshAgain=true;return;}marketplaceRefreshBusy=true;
  try{do{marketplaceRefreshAgain=false;const view=currentView;
    if(view==='home')await filterHomeProducts();
    if(view==='adminMonthlyListings'){
      const html=await renderAdminMonthlyListings();if(currentView===view){const tpl=document.createElement('template');tpl.innerHTML=html;
        document.querySelectorAll('#app [data-monthly-kind]').forEach(old=>{const next=tpl.content.querySelector(`[data-monthly-kind="${old.dataset.monthlyKind}"]`);if(next){next.classList.toggle('hidden',old.classList.contains('hidden'));old.replaceWith(next)}});
      }
    }
    if(view==='vendorProducts'){
      const host=document.querySelector('[data-vendor-listing-section="packages"]');if(host){const html=await renderVendorPackages(true);if(host.isConnected&&currentView===view)host.innerHTML=html;}
    }
    await refreshMonthlyPendingCount();
  }while(marketplaceRefreshAgain);}catch(err){console.warn('Marketplace realtime refresh failed',err);}finally{marketplaceRefreshBusy=false;}
}
// Marketplace realtime fires for ANY row change by ANY user. Re-fetching on every
// event multiplied traffic with the number of people online, so work is
// coalesced (one run per ~4s burst) and skipped while the tab is hidden (it
// runs once when the tab comes back).
let __mktTimer=null; const __mktPending=new Set();
function scheduleMarketplaceWork(kind){
  __mktPending.add(kind);
  if(document.hidden||__mktTimer)return;
  __mktTimer=setTimeout(()=>{
    __mktTimer=null;
    const kinds=[...__mktPending]; __mktPending.clear();
    if(kinds.includes('likes'))void hydrateProductLikeCountsInView();
    if(kinds.includes('variants'))void hydrateProductVariantIndicatorsInView();
    if(kinds.includes('regions'))void refreshMarketplaceRegions();
  },4000);
}
document.addEventListener('visibilitychange',()=>{ if(!document.hidden&&__mktPending.size&&!__mktTimer)scheduleMarketplaceWork('flush'); },{passive:true});
function subscribeMarketplaceUpdates(){
  const user=session?.user?.id||null;if(marketplaceLiveChannel&&marketplaceLiveUser===user)return;
  if(marketplaceLiveChannel){sb.removeChannel(marketplaceLiveChannel);marketplaceLiveChannel=null;}marketplaceLiveUser=user;if(!user)return;
  let channel=sb.channel(`marketplace-${user}`);
  for(const table of ['favorites','products','product_variants','vendor_packages','vendors','monthly_listing_submissions'])channel=channel.on('postgres_changes',{event:'*',schema:'public',table},payload=>{
    if(table==='favorites'){scheduleMarketplaceWork('likes');return;}
    invalidateMarketplaceState();
    if(table==='vendors'){const v=payload.new?.id?payload.new:payload.old;if(payload.eventType==='DELETE'||v.deleted_at||v.is_active===false)document.querySelectorAll(`[data-vendor-id="${CSS.escape(String(v.id))}"]`).forEach(el=>{if(el.classList.contains('vendor-card'))el.remove()});if(v.id===vendor?.id)refreshAuthState().catch(err=>console.warn('Vendor role refresh failed',err));}
    if(table==='product_variants')scheduleMarketplaceWork('variants');
    scheduleMarketplaceWork('regions');
  });
  marketplaceLiveChannel=channel.subscribe(status=>{window.__marketplaceRealtimeStatus=status;if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')console.warn('Marketplace realtime unavailable: check publication and RLS',status);});
}
// ---------- LIVE ORDERS ----------
let ordersLiveChannel = null;
let ordersLiveTimer = null;
let ordersLiveRefreshTimer = null;
let lastOrderScrollAt = 0;
let orderScrollWatchBound = false;
function ensureOrderScrollWatch() {
  if (orderScrollWatchBound) return;
  window.addEventListener("scroll", () => { lastOrderScrollAt = performance.now(); }, { passive:true });
  orderScrollWatchBound = true;
}
function refreshVisibleOrderView() {
  if (!["vendorOrders", "buyerOrders", "orderDetail", "orderHistory"].includes(currentView)) return;
  clearTimeout(ordersLiveRefreshTimer);

  const savedView = currentView;
  const savedParams = { ...(currentViewParams || {}) };

  // An open order detail is a live transaction surface. Do not wait for
  // scrolling to settle or for another timer: a status/payment change should
  // repaint immediately so the buyer/vendor sees the next step at once.
  if (savedView === "orderDetail") {
    ordersLiveRefreshTimer = setTimeout(async () => {
      if (currentView !== savedView) return;
      if (userIsTypingInApp()) { ordersLiveRefreshTimer = setTimeout(refreshVisibleOrderView, 2500); return; }
      try {
        await navigate(savedView, savedParams, false);
      } catch (err) {
        console.warn("[Levromart] Live order-detail refresh failed:", err);
      }
    }, 0);
    return;
  }

  // Order lists still wait briefly for an active scroll gesture so a realtime
  // event cannot make iOS jump while the customer/vendor is reading history.
  ensureOrderScrollWatch();
  const waitForScrollToSettle = () => {
    if (currentView !== savedView) return;
    const elapsed = performance.now() - lastOrderScrollAt;
    if (elapsed < 350) {
      ordersLiveRefreshTimer = setTimeout(waitForScrollToSettle, Math.max(80, 350 - elapsed));
      return;
    }
    ordersLiveRefreshTimer = setTimeout(async () => {
      if (currentView !== savedView) return;
      document.body.classList.add("orders-refreshing");
      try { await navigate(savedView, savedParams, false); }
      finally { requestAnimationFrame(() => document.body.classList.remove("orders-refreshing")); }
    }, 50);
  };
  waitForScrollToSettle();
}
let ordersVisibilityRefreshBound = false;
function handleOrdersVisibilityRefresh() {
  if (document.hidden || !["vendorOrders","buyerOrders","orderDetail","orderHistory","requestEquipment","vendorRequests"].includes(currentView)) return;
  clearTimeout(ordersLiveRefreshTimer);
  ordersLiveRefreshTimer = setTimeout(refreshAllLiveViews, 250);
}

// True while the person is typing into a field on the page. A live repaint would wipe what they have typed, so it waits.
function userIsTypingInApp() {
  const a = document.activeElement;
  if (!a || !a.closest || !a.closest("#app")) return false;
  const t = a.tagName;
  if (t === "TEXTAREA" || t === "SELECT") return String(a.value || "").length > 0;
  if (t === "INPUT") return !["button", "submit", "checkbox", "radio", "range", "file", "hidden"].includes(a.type) && String(a.value || "").length > 0;
  return false;
}
let requestsLiveTimer = null;
function refreshVisibleRequestView(tries) {
  const v = currentView;
  if (!["requestEquipment", "vendorRequests", "adminDisputes"].includes(v)) return;
  clearTimeout(requestsLiveTimer);
  const params = { ...(currentViewParams || {}) };
  requestsLiveTimer = setTimeout(async () => {
    if (currentView !== v) return;
    if (userIsTypingInApp() && (tries || 0) < 20) { refreshVisibleRequestView((tries || 0) + 1); return; }
    try { await navigate(v, params, false); } catch (err) { console.warn("[Levromart] Live request refresh failed:", err); }
  }, tries ? 2500 : 300);
}
function refreshAllLiveViews() { refreshVisibleOrderView(); refreshVisibleRequestView(0); }

// Safety net for a dropped or sleeping socket: while an order screen is open, a tiny query compares a fingerprint of
// the order(s) every few seconds and repaints only when something really changed (status, payment, proposal...).
let orderSignatureTimer = null;
const __orderSigs = new Map();
async function currentOrderSignature() {
  const uid = session?.user?.id; if (!uid) return null;
  if (currentView === "orderDetail") {
    const id = currentViewParams?.orderId; if (!id) return null;
    const [o, pays] = await Promise.all([
      sb.from("orders").select("status,status_changed_at,payment_unresolved_at,completed_at,cancelled_at,quantity_proposal,total_amount,payment_timing,delivery_fee").eq("id", id).maybeSingle(),
      sb.from("payments").select("id,status,amount").eq("order_id", id),
    ]);
    if (o.error) return null;
    return "d:" + id + JSON.stringify(o.data || {}) + JSON.stringify((pays.data || []).map((x) => [x.id, x.status, x.amount]));
  }
  if (["buyerOrders", "vendorOrders", "orderHistory"].includes(currentView)) {
    let q = sb.from("orders").select("id,status,status_changed_at,total_amount").order("created_at", { ascending: false }).limit(150);
    q = vendor?.id ? q.or(`buyer_id.eq.${uid},vendor_id.eq.${vendor.id}`) : q.eq("buyer_id", uid);
    const { data, error } = await q;
    if (error) return null;
    return "l:" + (data || []).map((r) => `${r.id}|${r.status}|${r.status_changed_at}|${r.total_amount}`).join(",");
  }
  return null;
}
function startOrderSignaturePoll() {
  if (orderSignatureTimer) return;
  orderSignatureTimer = setInterval(async () => {
    if (document.hidden || !session) return;
    if (!["orderDetail", "buyerOrders", "vendorOrders", "orderHistory"].includes(currentView)) { __orderSigs.clear(); return; }
    const key = currentView + ":" + (currentViewParams?.orderId || "");
    try {
      const sig = await currentOrderSignature();
      if (sig == null) return;
      const prev = __orderSigs.get(key);
      __orderSigs.set(key, sig);
      if (prev !== undefined && prev !== sig) refreshVisibleOrderView();
    } catch (_) {}
  }, 20000);
}

let orderBadgeTimer = null;
// Any order change also moves the Orders badge and the pending counts in the profile menu.
function onOrderLiveEvent() {
  refreshVisibleOrderView();
  clearTimeout(orderBadgeTimer);
  orderBadgeTimer = setTimeout(() => { try { window.__ordCnt = null; refreshNotifications(false).then(() => { try { renderBottomNav(); } catch (_) {} }).catch(() => {}); } catch (_) {} }, 700);
}
let liveResubTimer = null;
let liveEverSubscribed = false;
function subscribeOrderUpdates() {
  for (const ch of (window.__liveAuxChannels || [])) { try { sb.removeChannel(ch); } catch (e) {} }
  window.__liveAuxChannels = [];
  if (ordersLiveChannel) { try { sb.removeChannel(ordersLiveChannel); } catch (e) {} ordersLiveChannel = null; }
  if (ordersLiveTimer) { clearInterval(ordersLiveTimer); ordersLiveTimer = null; }
  clearTimeout(liveResubTimer);
  if (!session) return;

  // Each group lives on its own channel: one table that cannot be streamed must never take the others down with it.
  const status = (name) => (st) => {
    window["__" + name + "RealtimeStatus"] = st;
    if (st === "SUBSCRIBED") {
      // After a dropped connection nothing was replayed, so catch up straight away.
      if (liveEverSubscribed) refreshAllLiveViews();
      liveEverSubscribed = true;
    } else if (st === "CHANNEL_ERROR" || st === "TIMED_OUT") {
      console.warn("[Levromart] Live updates (" + name + ") unavailable:", st);
      clearTimeout(liveResubTimer);
      liveResubTimer = setTimeout(() => { if (session) subscribeOrderUpdates(); }, 5000);
    }
  };
  const uid = session.user.id, stamp = Date.now();

  ordersLiveChannel = sb.channel(`orders-live-${uid}-${stamp}`);
  if (profile?.role !== "admin") {
    // A vendor can be a seller and a buyer at once, so listen on both sides.
    if (vendor?.id) ordersLiveChannel.on("postgres_changes", { event: "*", schema: "public", table: "orders", filter: `vendor_id=eq.${vendor.id}` }, onOrderLiveEvent);
    ordersLiveChannel.on("postgres_changes", { event: "*", schema: "public", table: "orders", filter: `buyer_id=eq.${uid}` }, onOrderLiveEvent);
  } else {
    ordersLiveChannel.on("postgres_changes", { event: "*", schema: "public", table: "orders" }, onOrderLiveEvent);
  }
  ordersLiveChannel.on("postgres_changes", { event: "*", schema: "public", table: "payments" }, onOrderLiveEvent);
  ordersLiveChannel.subscribe(status("orders"));

  const aux = sb.channel(`order-extras-${uid}-${stamp}`);
  for (const table of ["order_items", "order_notes", "service_offers"]) aux.on("postgres_changes", { event: "*", schema: "public", table }, refreshVisibleOrderView);
  aux.subscribe(status("orderExtras"));

  const req = sb.channel(`requests-live-${uid}-${stamp}`);
  for (const table of ["equipment_requests", "request_offers", "disputes"]) req.on("postgres_changes", { event: "*", schema: "public", table }, () => refreshVisibleRequestView(0));
  req.subscribe(status("requests"));
  window.__liveAuxChannels = [aux, req];

  startOrderSignaturePoll();
  if (!ordersVisibilityRefreshBound) {
    document.addEventListener("visibilitychange", handleOrdersVisibilityRefresh, { passive:true });
    window.addEventListener("focus", handleOrdersVisibilityRefresh, { passive:true });
    window.addEventListener("online", refreshAllLiveViews, { passive:true });
    ordersVisibilityRefreshBound = true;
  }
}

// ---------- AUTH ----------
async function refreshAuthState() {
  const { data } = await sb.auth.getSession();
  session = data.session;

  // getSession() restores a cached JWT; it does not prove that the Auth user
  // still exists. After a hard account deletion, an already-issued access
  // token can remain readable locally until it expires. Validate the current
  // user before treating that cached session as a real login.
  //
  // That verification call and the profile-repair/role-sync work further
  // down used to run strictly back to back -- four full network round trips
  // in a row on every single login and session restore, which is most of
  // why logging in could visibly sit there for several seconds on a slow
  // connection. Neither of them actually needs verification to finish
  // first: they already have everything they need from this same cached
  // JWT, and a genuinely invalid token gets rejected on its own at the
  // database layer regardless of call order. Start them together and only
  // decide what to keep once verification resolves.
  let ensureProfileAndRoleSync = Promise.resolve(null);
  if (session) {
    ensureProfileAndRoleSync = (async () => {
      // A deleted account can be recreated with a brand-new Auth UUID. Repair
      // the public.users anchor before any buyer_id/vendor_id FK reads or writes.
      await ensureCustomerProfile();
      // Resolve the account role from the authoritative database state on every
      // session restore. This prevents a stale local/profile role from leaving an
      // approved vendor looking like a buyer until they log out and back in.
      // Pending/rejected vendor applications resolve back to buyer by design.
      try {
        const { data: resolvedRole, error: roleSyncError } = await sb.rpc("sync_current_account_role");
        if (!roleSyncError && resolvedRole) return resolvedRole;
        if (roleSyncError) console.warn("[Levromart] Authoritative role sync failed; using profile row:", roleSyncError);
      } catch (roleSyncException) {
        console.warn("[Levromart] Authoritative role sync exception:", roleSyncException);
      }
      return null;
    })();
    // Runs in the background regardless of what verification below decides;
    // its own console.warn calls are the only reporting it needs, so a
    // rejection here must never surface as an unhandled promise rejection.
    ensureProfileAndRoleSync.catch(() => {});
  }

  if (session) {
    let verifiedUser = null, verifyError = null;
    try {
      const r = await sb.auth.getUser();
      verifiedUser = r.data; verifyError = r.error;
    } catch (networkErr) {
      verifyError = networkErr;
    }
    // Only a real rejection of the token (expired/invalid/user gone) means the
    // account is actually gone -- a transient network/server hiccup talking to
    // Supabase must not be treated the same way, or a flaky connection forces
    // a perfectly valid session to sign out.
    const status = verifyError?.status ?? verifyError?.originalError?.status;
    const isAuthRejection = status === 401 || status === 403 || /user.?not.?found|session.?not.?found|invalid.*token|jwt/i.test(verifyError?.message || "");
    if (isAuthRejection || (!verifyError && !verifiedUser?.user)) {
      // Temporary diagnostic for a reported "logs in, then immediately logs
      // back out" bug that hasn't been reproduced yet -- this is the one
      // path in refreshAuthState() that forces a sign-out, so if that report
      // is this code misfiring on something that wasn't really an invalid
      // session, this toast is what will catch it in the act. Safe to
      // remove once that's confirmed one way or the other.
      console.warn("[Levromart] Auto sign-out triggered:", { status, message: verifyError?.message, isAuthRejection, hadVerifiedUser: !!verifiedUser?.user });
      showToast(`Signed out (diagnostic): ${verifyError?.message || (isAuthRejection ? "auth rejected" : "no user returned")}${status ? " · status " + status : ""}`, "error");
      session = null;
      profile = null;
      vendor = null;
      favoriteIds = new Set();
      packageFavoriteIds = new Set();
      manualLogout = true;
      await sb.auth.signOut({ scope: "local" }).catch(() => {});
    }
  }

  profile = null;
  vendor = null;
  favoriteIds = new Set();
  packageFavoriteIds = new Set();
  if (session) {
    const userId = session.user.id;

    // Almost always already settled by now, since it's been running since
    // right before the getUser() round trip above.
    const resolvedRole = await ensureProfileAndRoleSync;
    if (resolvedRole) {
      // The subsequent users query below is still the source of the complete
      // profile object; this local assignment only prevents a stale value
      // from being used by code that runs between the two requests.
      profile = profile || {};
      profile.role = resolvedRole;
      profile.role_selected = true;
    }

    const [profileRes, vendorRes, favsRes, pkgFavsRes] = await Promise.all([
      sb.from("users").select("*").eq("id", userId).single(),
      sb.from("vendors").select("*").eq("user_id", userId).is("deleted_at", null).maybeSingle(),
      sb.from("favorites").select("product_id").eq("buyer_id", userId),
      sb.from("package_favorites").select("package_id").eq("buyer_id", userId)
    ]);
    profile = profileRes.data;
    vendor = profile?.role === "admin" ? null : vendorRes.data;
    // profile.role comes straight from the users row, which
    // sync_current_account_role() (above, SECURITY DEFINER, immune to RLS
    // and run first) already made authoritative. Re-deriving it here a
    // second time from this vendors fetch used to silently downgrade a real
    // vendor back to buyer whenever that fetch merely errored or lagged
    // (a transient network hiccup, RLS timing) -- the vendors row exists and
    // is fine, only this second, redundant read of it failed. Trust the
    // already-synced role instead; `vendor` below stays purely for display
    // (stats, storefront info), not for deciding the role.
    favoriteIds = new Set((favsRes.data || []).map((f) => f.product_id));
    packageFavoriteIds = new Set((pkgFavsRes.data || []).map((f) => f.package_id));
  }
  updateAuthUI();
  renderBottomNav();
  // Badge/count refresh is independent of rendering the current page; do not
  // hold the initial app screen hostage to those background reads.
  refreshNotifications(false).catch(() => {});
  subscribeNotifications();
  subscribeOrderUpdates();
  subscribeMarketplaceUpdates();
  window.__monthlyPendingCount=0;void refreshMonthlyPendingCount();
  window.__lockedVendorCount=0;void refreshLockedVendorCount();
  loadAiVoices();
  // Google sign-in creates the account straight away with no chance to
  // pick buyer vs vendor first (unlike the manual signup form, which asks
  // up front) -- this catches that gap and asks right after, before the
  // account is treated as fully set up. Everything else that might need
  // asking (setting a password, the periodic OTP re-check) waits behind
  // this one, see runPostAuthChecks.
  if (profile && profile.role_selected === false) byId("roleSelectModal")?.classList.remove("hidden");
  else await runPostAuthChecks();
}
function openRequiredBuyerPhoneModal() {
  const modal = byId("requiredBuyerPhoneModal");
  if (!modal) return;
  const input = byId("requiredBuyerPhoneInput");
  const error = byId("requiredBuyerPhoneError");
  if (input) input.value = String(profile?.phone || "").trim();
  error?.classList.add("hidden");
  modal.classList.remove("hidden");
  setTimeout(() => input?.focus(), 50);
}

async function saveRequiredBuyerPhone() {
  if (!session?.user?.id || !profile) return;
  const input = byId("requiredBuyerPhoneInput");
  const error = byId("requiredBuyerPhoneError");
  const btn = byId("requiredBuyerPhoneSaveBtn");
  const phone = String(input?.value || "").trim();
  const normalized = phone.replace(/[\s().-]/g, "");
  error?.classList.add("hidden");
  if (!phone) { if(error){error.textContent="Phone number is required.";error.classList.remove("hidden");} return; }
  if (!/^\+?[0-9]{7,15}$/.test(normalized)) {
    if(error){error.textContent="Enter a valid phone number (7–15 digits).";error.classList.remove("hidden");}
    return;
  }
  if (btn) { btn.disabled=true; btn.classList.add("is-busy"); }
  try {
    const { error: updateError } = await sb.from("users").update({ phone }).eq("id", session.user.id);
    if (updateError) throw updateError;
    profile.phone = phone;
    byId("requiredBuyerPhoneModal")?.classList.add("hidden");
    updateAuthUI();
    showToast("Phone number saved.", "success");
    await runPostAuthChecks();
  } catch (e) {
    if(error){error.textContent=e?.message || "Could not save your phone number.";error.classList.remove("hidden");}
  } finally {
    if (btn) { btn.disabled=false; btn.classList.remove("is-busy"); }
  }
}

async function chooseAccountRole(role) {
  // Selecting Vendor means "I want to apply", not "I am already an approved
  // vendor". The database becomes authoritative only after approval.
  const authoritativeRole = role === "vendor" ? "buyer" : role;
  const { error } = await sb.from("users").update({ role: authoritativeRole, role_selected: true }).eq("id", session.user.id);
  if (error) { showToast(error.message, "error"); return; }
  profile.role = authoritativeRole;
  profile.role_selected = true;
  byId("roleSelectModal")?.classList.add("hidden");
  updateAuthUI();
  renderBottomNav();
  if (role === "vendor") navigate("vendorApply");
  else showToast("You're all set.", "success");
  await runPostAuthChecks();
}

async function setAccountPassword() {
  const pw = byId("setPasswordInput").value;
  const confirm = byId("setPasswordConfirmInput").value;
  const errorEl = byId("setPasswordError");
  errorEl.classList.add("hidden");
  if (pw.length < 8) { errorEl.textContent = "Password must be at least 8 characters."; errorEl.classList.remove("hidden"); return; }
  if (pw !== confirm) { errorEl.textContent = "Passwords don't match."; errorEl.classList.remove("hidden"); return; }
  // Set via the server's admin API (api/auth-otp.js), not the client
  // auth.updateUser() call -- a Google-only account has no password to
  // compare against, and Supabase's own client-side "must differ from the
  // old password" check has a known rough edge that misfires in exactly
  // that case. The admin path sets it directly and skips that check.
  try {
    const res = await fetch("/api/auth-otp", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "set-password", accessToken: session.access_token, password: pw }),
    });
    const json = await res.json();
    if (!res.ok || json.error) throw new Error(json.error || "Could not set password.");
  } catch (err) {
    errorEl.textContent = err.message;
    errorEl.classList.remove("hidden");
    return;
  }
  profile.has_password = true;
  byId("setPasswordModal").classList.add("hidden");
  byId("setPasswordInput").value = "";
  byId("setPasswordConfirmInput").value = "";
  showToast("Password set. You can now log in with it too.", "success");
  await runPostAuthChecks();
}

// Sequenced so at most one of these modals is ever open at a time: a
// Google account with no password set yet gets asked first (this is what
// lets password-based actions like deleting the account work uniformly
// for every account, Google or not); only once that's resolved does the
// periodic email-OTP re-check run. otpCheckDoneThisBoot keeps the OTP
// check from firing again on every token-refresh-triggered auth-state
// change within the same page load -- it only needs to run once per
// actual app open (a real reload naturally resets it).
let otpCheckDoneThisBoot = false;
async function runPostAuthChecks() {
  if (!profile || !session) return;
  // Every customer account must have a phone number. Manual registration already
  // collects it; this gate covers Google sign-in and older accounts that predate
  // the requirement. Do this before the password/OTP checks so the account cannot
  // proceed as a fully configured buyer until the contact number is supplied.
  if (profile.role === "buyer" && !String(profile.phone || "").trim()) {
    openRequiredBuyerPhoneModal();
    return;
  }
  if (profile.has_password === false) { byId("setPasswordModal")?.classList.remove("hidden"); return; }
  // A vendor (pending or approved) with no payout account can't actually be
  // paid for any sale. This isn't a hard block like the checks above --
  // "Remind me later" just closes it for this session -- but it comes back
  // on every fresh login until paystack_subaccount_code is actually set,
  // at which point this condition is simply false and it never shows again.
  if (vendor && !vendor.paystack_subaccount_code) { byId("vendorPayoutNudgeModal")?.classList.remove("hidden"); return; }
  // Admin sign-in no longer requires the extra 6-digit email code -- removed
  // per request. checkOtpRequirement()/the otpModal are left in place but
  // unused rather than deleted, in case this needs to come back.
}
function openVendorPayoutSetup() {
  byId("vendorPayoutNudgeModal")?.classList.add("hidden");
  navigate("vendorEditProfile");
}
function dismissVendorPayoutNudge() {
  byId("vendorPayoutNudgeModal")?.classList.add("hidden");
}
// One shared identity re-check for every path that can land someone in the
// app: password login, Google OAuth, and simply reopening the app after
// the 7-day window has lapsed on a still-valid session. The server (see
// api/auth-otp.js) is the one deciding whether it's actually due, based on
// users.otp_verified_at, not the client.
async function checkOtpRequirement(accessToken) {
  if (profile?.role !== "admin") return;
  let otpJson = {};
  try {
    const res = await fetch("/api/auth-otp", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "send", accessToken }),
    });
    otpJson = await res.json();
  } catch (e) {
    // A network hiccup on this check shouldn't lock someone out of an
    // already-valid session -- fail open, same as the account-status check.
    return;
  }
  if (!otpJson.otpRequired) return;
  pendingOtpAccessToken = accessToken;
  byId("otpInput").value = "";
  byId("otpError").classList.add("hidden");
  byId("otpModal").classList.remove("hidden");
  setTimeout(() => byId("otpInput")?.focus(), 50);
}

