          <div class="lv-pp-group">${links.map((l) => `<button type="button" class="lv-pp-row"${l.profileKey ? ` data-profile-key="${esc(l.profileKey)}"` : ""} onclick="closeAllPanels();${l.action}">${l.label}</button>`).join("")}</div>
