// Nothing typed yet doesn't have to mean nothing shown -- surface the most
// popular active listings (view_count) so the page never opens to a blank
// screen. Same price-then-distance ordering as an actual search.
let searchSuggestionsLoaded = false;
// Two modes: with no argument, this is the page's own empty-input default
// (only ever shows while the box is empty). With forceWithTerm, it's the
// "no real matches" fallback from runSearchPageQuery -- a search must never
// dead-end on a bare "no results" screen, so a typed query that matched
// nothing still gets a popularity-ranked list underneath the honest "no
// matches" note, rather than nothing at all.
async function renderSearchPageSuggestions(forceWithTerm) {
  const results = byId("searchPageResults");
  if (!results) return;
  const stillCurrent = () => {
    const t = byId("searchPageInput")?.value.trim() || "";
    return forceWithTerm ? t === forceWithTerm : !t;
  };
  if (!stillCurrent()) return;
  // Pull a wider pool than what's actually shown, then run it through the
  // same fairness shuffle Browse Everything uses (a new arrangement every
  // 10 minutes) instead of always ranking by raw view_count -- otherwise
  // the same already-popular handful of listings owns this slot forever,
  // and everything else never gets a turn at it.
  const { data } = await sb.from("products")
    .select("id,name,photos,sale_price,discount_price,rental_rate,rental_rate_unit,is_service,listing_type,service_price_unit,category:categories(sector_id),vendor:vendors!inner(id,business_name,verification_status,is_active,lat,lng,avg_rating,review_count)")
    .eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true)
    .order("view_count", { ascending: false }).limit(60);
  if (!stillCurrent()) return; // typing moved on while this was in flight
  const pool = deterministicBrowseVisibilityShuffle(data || [], "search-suggestions").slice(0, 12);
  const prods = sortSearchResultsByPriceThenDistance(pool, searchResultEffectivePrice);
  if (!prods.length) return;
  searchSuggestionsLoaded = true;
  // Forced mode keeps the "no matches" note in place above the fallback
  // list; the default empty-input mode has no such note to preserve.
  document.querySelectorAll(forceWithTerm ? ".search-page-section" : ".search-page-section, .search-page-empty").forEach((el) => el.remove());
  results.insertAdjacentHTML("beforeend", `<div class="search-page-section"><h3>${forceWithTerm ? "Popular right now" : "Suggested for you"}</h3>${prods.map(searchProductRowHtml).join("")}</div>`);
  if (!buyerLocation) {
    getCustomerLocation().then(() => { if (stillCurrent()) renderSearchPageSuggestions(forceWithTerm); }).catch(() => {});
  }
}
async function renderRelatedSuggestions(term, seq) {
  try {
    const words = String(term).toLowerCase().split(/\s+/).filter((w) => w.length > 2);
    const stems = [...new Set(words.flatMap((w) => [w.replace(/(es|s)$/, ""), w.slice(0, Math.max(3, Math.ceil(w.length * 0.6)))]))].filter((w) => w.length > 2);
    for (const q of stems) {
      if (seq !== searchPageSeq) return false;
      const { data, error } = await sb.rpc("search_products_full_v2", { p_query: q, p_limit: 12 });
      if (error || !data?.length) continue;
      if (seq !== searchPageSeq) return false;
      const prods = sortSearchResultsByPriceThenDistance(data.map((r) => ({
        id: r.id, name: r.name, photos: r.photos, sale_price: r.sale_price, discount_price: r.discount_price, rental_rate: r.rental_rate, rental_rate_unit: r.rental_rate_unit,
        is_service: r.is_service, listing_type: r.listing_type, service_price_unit: r.service_price_unit,
        vendor: { id: r.vendor_id, business_name: r.vendor_business_name, lat: r.vendor_lat, lng: r.vendor_lng, avg_rating: r.vendor_avg_rating, review_count: r.vendor_review_count },
      })), searchResultEffectivePrice);
      byId("searchPageResults")?.insertAdjacentHTML("beforeend", `<div class="search-page-section"><h3>You might be looking for</h3>${prods.map(searchProductRowHtml).join("")}</div>`);
      return true;
    }
  } catch (_) {}
  return false;
}
let searchPageAbortController = null;

// ---------- typo-tolerant search helpers ----------
function lvNorm(x){ return String(x||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9 ]+/g," ").replace(/\s+/g," ").trim(); }
function lvLev(a,b){
  if(a===b) return 0; const m=a.length,n=b.length; if(!m) return n; if(!n) return m;
  let prev=Array.from({length:n+1},(_,j)=>j);
  for(let i=1;i<=m;i++){ const cur=[i]; for(let j=1;j<=n;j++){ cur[j]=Math.min(prev[j]+1,cur[j-1]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1)); } prev=cur; }
  return prev[n];
}
function lvFuzzyScore(q,name){
  q=lvNorm(q); const n=lvNorm(name); if(!q||!n) return null;
  if(n.includes(q)) return 0;
  const maxd=q.length<=3?0:q.length<=5?1:q.length<=8?2:3;
  let best=99;
  for(const w of n.split(" ")){ if(!w) continue; best=Math.min(best,lvLev(q,w),lvLev(q,w.slice(0,q.length+1))); }
  if(best<=maxd) return 1+best;
  if(q.length>=4){
    const flat=n.replace(/ /g,""); let i=0; for(const c of flat){ if(c===q[i]) i++; if(i===q.length) break; }
    if(i===q.length) return 6;
    const cnt={}; for(const c of flat) cnt[c]=(cnt[c]||0)+1;
    let ok=true; for(const c of q.replace(/ /g,"")){ if(!cnt[c]){ ok=false; break; } cnt[c]--; }
    if(ok) return 7;
  }
  return null;
}
async function lvFuzzyNameIndex(kind){
  window.__lvFuzzyIdx=window.__lvFuzzyIdx||{};
  const hit=window.__lvFuzzyIdx[kind];
  if(hit&&Date.now()-hit.at<600000) return hit.rows;
  let rows=[];
  if(kind==="products"){
    const r=await sb.from("products").select("id,name,vendor:vendors!inner(id)").eq("status","active").eq("vendor.verification_status","verified").eq("vendor.is_active",true).range(0,2999);
    rows=(r.data||[]).map(x=>({id:x.id,name:x.name}));
  }else{
    const r=await sb.from("vendors").select("id,business_name").eq("verification_status","verified").eq("is_active",true).range(0,2999);
    rows=(r.data||[]).map(x=>({id:x.id,name:x.business_name}));
  }
  window.__lvFuzzyIdx[kind]={at:Date.now(),rows};
  return rows;
}
async function lvMergeFuzzyProducts(term,existing,kind){
  const have=new Set(existing.map(r=>String(r.id)));
  const idx=await lvFuzzyNameIndex("products");
  const hits=idx.map(x=>({id:x.id,s:lvFuzzyScore(term,x.name)})).filter(x=>x.s!=null&&!have.has(String(x.id))).sort((a,b)=>a.s-b.s).slice(0,12);
  if(!hits.length) return existing;
  const r=await sb.from("products").select("id,name,photos,sale_price,discount_price,rental_rate,rental_rate_unit,is_service,listing_type,service_price_unit,vendor_id,vendor:vendors(business_name,lat,lng,avg_rating,review_count)").in("id",hits.map(h=>h.id)).eq("status","active");
  const byId_=new Map((r.data||[]).map(x=>[String(x.id),x]));
  const extra=hits.map(h=>byId_.get(String(h.id))).filter(Boolean).filter(p=>kind==="products"?!p.is_service:kind==="services"?!!p.is_service:true).map(p=>({...p,vendor_business_name:p.vendor?.business_name,vendor_lat:p.vendor?.lat,vendor_lng:p.vendor?.lng,vendor_avg_rating:p.vendor?.avg_rating,vendor_review_count:p.vendor?.review_count}));
  return [...existing,...extra];
}
async function lvMergeFuzzyVendors(term,existing){
  const have=new Set(existing.map(v=>String(v.id)));
  const idx=await lvFuzzyNameIndex("vendors");
  const hits=idx.map(x=>({id:x.id,s:lvFuzzyScore(term,x.name)})).filter(x=>x.s!=null&&!have.has(String(x.id))).sort((a,b)=>a.s-b.s).slice(0,8);
  if(!hits.length) return existing;
  const r=await sb.from("vendors").select("id,business_name,logo_url,city,lat,lng,avg_rating,review_count,sector_id").in("id",hits.map(h=>h.id)).eq("verification_status","verified").eq("is_active",true);
  const m=new Map((r.data||[]).map(x=>[String(x.id),x]));
  return [...existing,...hits.map(h=>m.get(String(h.id))).filter(Boolean)];
}
async function runSearchPageQuery(term, saveToHistory) {
  term = String(term || "").trim();
  if (!term) return;
  const mySeq = ++searchPageSeq;
  // Abort whatever the previous keystroke's still-in-flight request was --
  // on a slow/high-latency connection, letting superseded requests keep
  // running just competes with this one for bandwidth and connection slots,
  // making the result the user actually wants arrive even later.
  searchPageAbortController?.abort();
  const controller = new AbortController();
  searchPageAbortController = controller;
  const historyBlock = byId("searchPageHistoryBlock");
  if (historyBlock) historyBlock.hidden = true;
  if (saveToHistory) writeSearchHistory(term);
  const kind = searchPageFilter;
  const wantProducts = kind === "all" || kind === "products" || kind === "services";
  const wantVendors = kind === "all" || kind === "vendors";
  const wantPackages = kind === "all" || kind === "packages";
  let fullRows = [], vends = [], packageRows = [];
  const enc = term.toLowerCase();
  const resultsEl = byId("searchPageResults");
  if (resultsEl && !resultsEl.querySelector(".search-page-section:not(.sr-skel)")) {
    resultsEl.querySelectorAll(".search-page-empty, .search-page-error, .sr-skel").forEach((el) => el.remove());
    resultsEl.insertAdjacentHTML("beforeend", searchSkeletonHtml());
  }
  try {
    // Only the entity types the active tab needs are requested. A single RPC
    // returns full product+vendor fields (no second hydration round trip);
    // Products/Services ask for a wider page and keep their own kind.
    [fullRows, vends, packageRows] = await Promise.all([
      wantProducts ? searchCached(`p2:${kind === "all" ? 20 : 60}:${enc}`, async () => {
        const args = { p_query: term, p_limit: kind === "all" ? 20 : 60 };
        const r = await sb.rpc("search_products_full_v2", args).abortSignal(controller.signal);
        // Older database without the richer function: fall back to the original one.
        return r.error && !controller.signal.aborted ? sb.rpc("search_products_full", args).abortSignal(controller.signal) : r;
      }, controller.signal, true) : [],
      wantVendors ? searchCached(`v2:${kind === "all" ? 6 : 30}:${enc}`, async () => {
        // Vendors match by shop name AND by what they sell: a search for a product or service also surfaces the shops offering it.
        const limit = kind === "all" ? 6 : 30;
        const vendorCols = "id,business_name,logo_url,city,lat,lng,avg_rating,review_count,sector_id";
        const byName = await sb.from("vendors").select(vendorCols).eq("verification_status", "verified").eq("is_active", true).ilike("business_name", `%${term}%`).limit(limit).abortSignal(controller.signal);
        if (byName.error) return byName;
        let prodRes = await sb.rpc("search_products_full_v2", { p_query: term, p_limit: 40 }).abortSignal(controller.signal);
        if (prodRes.error && !controller.signal.aborted) prodRes = await sb.rpc("search_products_full", { p_query: term, p_limit: 40 }).abortSignal(controller.signal);
        const known = new Set((byName.data || []).map((v) => String(v.id)));
        const ids = [...new Set((prodRes.data || []).map((r) => r.vendor_id).filter(Boolean).map(String))].filter((id) => !known.has(id)).slice(0, limit);
        let extra = [];
        if (ids.length) {
          const r = await sb.from("vendors").select(vendorCols).in("id", ids).eq("verification_status", "verified").eq("is_active", true).abortSignal(controller.signal);
          extra = r.data || [];
        }
        return { data: [...(byName.data || []), ...extra].slice(0, limit), error: null };
      }, controller.signal, true) : [],
      wantPackages ? searchCached(`k:${kind === "all" ? 6 : 30}:${enc}`, () => sb.from("vendor_packages").select("id,name,price,photos,items:package_items(quantity),vendor:vendors!inner(id,business_name,verification_status,is_active,lat,lng,avg_rating,review_count)").eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true).or(`name.ilike.%${term}%,description.ilike.%${term}%`).limit(kind === "all" ? 6 : 30).abortSignal(controller.signal), controller.signal, true) : [],
    ]);
  } catch (err) {
    if (controller.signal.aborted) return; // superseded by a newer keystroke
    if (mySeq !== searchPageSeq) return;
    const box = byId("searchPageResults");
    if (box) {
      box.querySelectorAll(".search-page-section, .search-page-empty, .search-page-error").forEach((el) => el.remove());
      box.insertAdjacentHTML("beforeend", `<div class="search-page-error" role="alert"><i class="fa-solid fa-triangle-exclamation"></i><strong>Couldn't search right now.</strong><p>Check your connection and try again.</p><button type="button" class="vl-add sr-retry" onclick="runSearchPageQuery(${JSON.stringify(term).replace(/"/g, "&quot;")},false)"><i class="fa-solid fa-rotate-right"></i> Try again</button></div>`);
    }
    return;
  }
  if (mySeq !== searchPageSeq) return;
  let productRows = (fullRows || []).filter((r) => kind === "products" ? !r.is_service : kind === "services" ? !!r.is_service : true).slice(0, kind === "all" ? 20 : 30);
  // Typo-tolerant fallback: a search with few exact hits also lists names that nearly match ("togernu" finds "tigernut").
  if (wantProducts && productRows.length < 4 && term.length >= 3) {
    try { productRows = await lvMergeFuzzyProducts(term, productRows, kind); } catch (_) {}
    if (mySeq !== searchPageSeq) return;
  }
  if (wantVendors && (vends || []).length < 2 && term.length >= 3) {
    try { vends = await lvMergeFuzzyVendors(term, vends || []); } catch (_) {}
    if (mySeq !== searchPageSeq) return;
  }
  // Keep the server's relevance order (best name match first); never re-sort by price.
  const prods = productRows.map((r) => ({
    id: r.id, name: r.name, photos: r.photos, sale_price: r.sale_price, discount_price: r.discount_price,
    rental_rate: r.rental_rate, rental_rate_unit: r.rental_rate_unit, is_service: r.is_service,
    listing_type: r.listing_type, service_price_unit: r.service_price_unit,
    vendor: { id: r.vendor_id, business_name: r.vendor_business_name, lat: r.vendor_lat, lng: r.vendor_lng, avg_rating: r.vendor_avg_rating, review_count: r.vendor_review_count },
  }));
  const vendList = buyerLocation ? [...(vends || [])].sort((a, b) => {
    const da = searchResultDistanceKm(a), db = searchResultDistanceKm(b);
    if (da == null && db == null) return 0;
    if (da == null) return 1;
    if (db == null) return -1;
    return da - db;
  }) : (vends || []);
  const packageList = sortSearchResultsByPriceThenDistance(packageRows || [], (pkg) => pkg.price ?? null);

  const results = byId("searchPageResults");
  if (!results) return;
  // Follower counts for the vendors shown (memoised for 3 minutes, one RPC at most).
  const vendListHydrated = vendList.length ? await attachVendorFollowerCounts(vendList) : [];
  if (mySeq !== searchPageSeq) return;
  document.querySelectorAll(".search-page-section, .search-page-empty, .search-page-error").forEach((el) => el.remove());

  const single = kind !== "all";
  const sections = [
    prods.length ? { title: single ? "" : `Products (${prods.length})`, rows: prods.map(searchProductRowHtml) } : null,
    vendList.length ? { title: single ? "" : `Vendors (${vendList.length})`, rows: vendListHydrated.map(searchVendorRowHtml) } : null,
    packageList.length ? { title: single ? "" : `Packages (${packageList.length})`, rows: packageList.map(searchPackageRowHtml) } : null,
  ].filter(Boolean);

  if (!sections.length) {
    // A dead end here (an empty screen with nothing to tap) is worse than an
    // honest "no exact match" note followed by something -- so this always
    // falls through to the same popularity-ranked list the page opens with,
    // clearly labeled as not a match rather than dressed up as one.
    const popularFallback = kind === "all" || kind === "products";
    const noun = { all: "results", products: "products", vendors: "vendors", services: "services", packages: "packages" }[kind];
    results.insertAdjacentHTML("beforeend", `<div class="search-page-empty"><i class="fa-solid fa-magnifying-glass"></i><strong>No results found</strong><p>No ${noun} match "${esc(term)}". Try another search or browse our marketplace.</p><div class="search-empty-actions"><button type="button" class="vl-add sr-retry" onclick="navigate('vendors')"><i class="fa-solid fa-store"></i> Browse vendors</button><button type="button" class="sr-secondary" onclick="navigate('home')"><i class="fa-solid fa-table-cells-large"></i> Browse categories</button></div>${popularFallback ? `<p class="search-empty-note">Here's what's popular right now.</p>` : ""}</div>`);
    // Never a dead end: first try related listings (shorter stem of the words typed), then fall back to what is popular.
    if (!(await renderRelatedSuggestions(term, mySeq))) { if (mySeq === searchPageSeq) await renderSearchPageSuggestions(term); }
  } else {
    results.insertAdjacentHTML("beforeend", sections.map((s) => `<div class="search-page-section">${s.title ? `<h3>${esc(s.title)}</h3>` : ""}${s.rows.join("")}</div>`).join(""));
  }

  // Distances are only shown once we actually have the buyer's position.
  // Kick off (or reuse) that request in the background and quietly re-run
  // this exact query once it resolves, rather than blocking the first paint
  // on a GPS fix.
  if (!buyerLocation) {
    getCustomerLocation().then(() => { if (mySeq === searchPageSeq) runSearchPageQuery(term, false); }).catch(() => {});
  }
}

const PRODUCT_LIST_SELECT = "id, name, category_id, listing_type, sale_price, discount_price, rental_rate, rental_rate_unit, photos, quantity_available, condition, is_service, service_price_unit, payment_timing, payment_deposit_percent, delivery_fee, delivery_fee_mode, delivery_fee_per_km, vendor:vendors!inner(id, business_name, verification_status, logo_url, delivery_fee, delivery_fee_mode, delivery_fee_per_km, lat, lng), category:categories(sector_id)";

// Used whenever a search/filter comes up empty - instead of a dead end,
// show what IS available so the customer isn't stuck looking at nothing.
async function fetchFallbackProducts(excludeIds) {
  if (browserLooksOffline()) {
    const cache = getOfflineHomeCache();
    return offlineFilterProducts(cache?.browseProducts || [], "", "", "", currentSectorId).filter(p => !excludeIds?.includes(p.id)).slice(0, 8);
  }
  let q = sb
    .from("products")
    .select(PRODUCT_LIST_SELECT)
    .eq("status", "active")
    .eq("vendor.verification_status", "verified")
    .eq("vendor.is_active", true);
  if (currentSectorId) q = q.eq("category.sector_id", currentSectorId);
  if (excludeIds?.length) q = q.not("id", "in", `(${excludeIds.join(",")})`);
  const { data } = await q.order("created_at", { ascending: false }).limit(8);
  return data || [];
}

function noResultsWithFallbackHtml(message, fallback) {
  const notice = `<div class="empty-state" style="grid-column:1/-1;padding:1.5rem 1rem;">${esc(message)}</div>`;
  if (!fallback.length) return `<div class="empty-state">No products found. Vendors, start listing!</div>`;
  return notice + fallback.map(productCardHtml).join("");
}

let homeSearchTimer = null;
function scheduleHomeSearch() {
  clearTimeout(homeSearchTimer);
  homeSearchTimer = setTimeout(() => filterHomeProducts(), 160);
}

async function searchHomePackages(term) {
  const q = String(term || "").trim();
  if (!q) return [];
  if (browserLooksOffline()) {
    const needle = q.toLowerCase();
    const cache = getOfflineHomeCache();
    return (cache?.packages || []).filter(pkg => `${pkg.name || ""} ${pkg.description || ""} ${(pkg.items || []).map(it => it.product?.name || "").join(" ")}`.toLowerCase().includes(needle)).slice(0, 8);
  }
  const [{ data: direct }, { data: itemMatches }] = await Promise.all([
    sb.from("vendor_packages").select("id, vendor_id, name, description, price, photos, created_at, vendor:vendors!inner(id,business_name,logo_url,delivery_fee,verification_status,is_active), items:package_items(quantity, product:products(id,name,category_id,photos,category:categories(name,sector_id)))")
      .eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true)
      .or(`name.ilike.%${q}%,description.ilike.%${q}%`).limit(8),
    sb.from("package_items").select("package_id, product:products!inner(name,description)").ilike("product.name", `%${q}%`).limit(30),
  ]);
  const ids = [...new Set([...(direct || []).map((p) => p.id), ...(itemMatches || []).map((r) => r.package_id)])].slice(0, 8);
  if (!ids.length) return [];
  const directById = new Map((direct || []).map((p) => [p.id, p]));
  const missing = ids.filter((id) => !directById.has(id));
  if (missing.length) {
    const { data } = await sb.from("vendor_packages").select("id, vendor_id, name, description, price, photos, created_at, vendor:vendors!inner(id,business_name,logo_url,delivery_fee,verification_status,is_active), items:package_items(quantity, product:products(id,name,category_id,photos,category:categories(name,sector_id)))")
      .eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true).in("id", missing);
    (data || []).forEach((p) => directById.set(p.id, p));
  }
  return ids.map((id) => directById.get(id)).filter(Boolean);
}

async function renderHomePackageSearch(term) {
  const wrap = byId("packageSearchResults");
  if (!wrap) return;
  const q = String(term || "").trim();
  if (!q) { wrap.classList.add("hidden"); wrap.innerHTML = ""; return; }
  wrap.classList.remove("hidden");
  wrap.innerHTML = `<h3 class="section-title"><span><i class="fa-solid fa-box-open"></i> Package matches</span></h3><p class="muted">Searching packages…</p>`;
  const packages = await searchHomePackages(q);
  if (byId("searchInput")?.value.trim() !== q) return;
  wrap.innerHTML = packages.length
    ? `<h3 class="section-title"><span><i class="fa-solid fa-box-open"></i> Package matches</span></h3><div class="grid">${packages.map((pkg) => packageCardHtml(pkg, pkg.vendor?.delivery_fee)).join("")}</div>`
    : `<h3 class="section-title"><span><i class="fa-solid fa-box-open"></i> Package matches</span></h3><div class="empty-state">No package matches for “${esc(q)}”.</div>`;
}

function switchHomeListingTab(tab) {
  homeListingTab = ["products", "services", "packages"].includes(tab) ? tab : "products";
  document.querySelectorAll(".home-catalog-type-tabs .catalog-type-tab").forEach((b) => {
    const key = b.dataset.tab || b.textContent.trim().toLowerCase();
    b.classList.toggle("active", key === homeListingTab);
  });
  const grid = byId("productGrid");
  const packageResults = byId("packageSearchResults");
  const listingFilter = byId("filterListing");
  const categoryFilter = byId("filterCategory");
  if (homeListingTab === "packages") {
    if (listingFilter) listingFilter.style.display = "none";
    if (categoryFilter) categoryFilter.style.display = "none";
    if (packageResults) { packageResults.classList.add("hidden"); packageResults.innerHTML = ""; }
    if (grid) grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><i class="fa-solid fa-spinner fa-spin"></i> Loading packages…</div>`;
    renderHomePackageTab().catch((err) => {
      console.warn("[Levromart] Home package tab failed:", err);
      if (grid) grid.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><i class="fa-solid fa-box-open" style="display:block;font-size:1.5rem;margin-bottom:.5rem;"></i>Unable to load packages right now. Please try again.</div>`;
    });
  } else {
    if (listingFilter) listingFilter.style.display = "";
    if (categoryFilter) categoryFilter.style.display = "";
    if (browseFilterTrigger) browseFilterTrigger.style.display = "";
    syncBrowseFilterLabels();
    filterHomeProducts();
  }
}

async function loadHomePackagesForTab() {
  const allCached = Array.isArray(window.__allHomePackages) ? window.__allHomePackages : null;
  if (allCached) return allCached;
  const cached = getOfflineHomeCache()?.packages || [];
  if (cached.length && browserLooksOffline()) {
    window.__allHomePackages = cached;
    window.__homePackages = cached;
    return cached;
  }
  const { data, error } = await sb.from("vendor_packages")
    .select("id, vendor_id, name, description, price, photos, created_at, vendor:vendors!inner(id,business_name,logo_url,delivery_fee,verification_status,is_active), items:package_items(quantity, product:products(id,name,category_id,photos,category:categories(name,sector_id)))")
    .eq("status", "active")
    .eq("vendor.verification_status", "verified")
    .eq("vendor.is_active", true)
    .order("created_at", { ascending:false })
    .limit(50);
  if (error) throw error;
  window.__allHomePackages = data || [];
  window.__homePackages = window.__allHomePackages;
  return window.__allHomePackages;
}

async function renderHomePackageTab() {
  const grid = byId("productGrid");
  if (!grid || homeListingTab !== "packages") return;
  const q = (byId("searchInput")?.value || "").trim().toLowerCase();
  const all = await loadHomePackagesForTab();
  if (homeListingTab !== "packages") return;
  const shown = q ? all.filter(pkg => {
    const text = [pkg.name, pkg.description, ...(pkg.items || []).map(it => it.product?.name || "")].join(" ").toLowerCase();
    return text.includes(q);
  }) : all;
  grid.innerHTML = shown.length
    ? shown.map(pkg => packageCardHtml(pkg, pkg.vendor?.delivery_fee)).join("")
    : `<div class="empty-state" style="grid-column:1/-1;"><i class="fa-solid fa-box-open" style="display:block;font-size:1.5rem;margin-bottom:.5rem;"></i>No packages${q ? ` match “${esc(q)}”` : " available"}.</div>`;
}
function toggleBrowseFilters(force){
  const panel=byId("browseFilterPanel"), trigger=byId("browseFilterTrigger");
  if(!panel||!trigger)return;
  const open = typeof force === "boolean" ? force : panel.classList.contains("hidden");
  panel.classList.toggle("hidden",!open);
  trigger.setAttribute("aria-expanded",String(open));
  trigger.classList.toggle("active",open);
  if(!open){ ["listing","category"].forEach(k=>byId(`browse${k.charAt(0).toUpperCase()+k.slice(1)}Submenu`)?.classList.add("hidden")); }
}
function toggleBrowseSubmenu(kind){
  const id=kind==="listing"?"browseListingSubmenu":kind==="sort"?"browseSortSubmenu":"browseCategorySubmenu";
  const el=byId(id); if(!el)return;
  el.classList.toggle("hidden");
  if(kind==="category" && !el.classList.contains("hidden")) setTimeout(()=>byId("filterCategorySearch")?.focus(),40);
}
function syncBrowseFilterLabels(){
  const listing=byId("filterListing")?.value||"";
  const cat=byId("filterCategory")?.value||"";
  const l=byId("browseListingLabel"); if(l) l.textContent=listing==="rent"?"Rent":listing==="sale"?"Buy":"All types";
  const c=byId("browseCategoryLabel");
  if(c){ const selected=byId("filterCategory")?.options?.[byId("filterCategory")?.selectedIndex||0]; c.textContent=selected?.textContent||"All categories"; }
}
async function ensureVendorCoords(){
  if(window.__vendorCoords)return window.__vendorCoords;
  const map=new Map();
  try{
    for(let off=0;off<20000;off+=1000){
      const {data,error}=await sb.from("vendors").select("id,lat,lng").eq("verification_status","verified").eq("is_active",true).order("id").range(off,off+999);
      if(error)break;
      (data||[]).forEach(v=>{ if(v.lat!=null&&v.lng!=null&&Number.isFinite(Number(v.lat))&&Number.isFinite(Number(v.lng))) map.set(String(v.id),{lat:Number(v.lat),lng:Number(v.lng)}); });
      if(!data||data.length<1000)break;
    }
  }catch(_){}
  window.__vendorCoords=map;
  return map;
}
async function chooseBrowseSort(value,label){
  byId("browseSortSubmenu")?.classList.add("hidden");
  if(value==="near"){
    try{ if(!buyerLocation) await requestCustomerLocation(true); }catch(_){}
    if(!buyerLocation){ showToast?.("Turn on location to sort by closest to you."); return; }
  }
  window.__browseSort=value;
  const l=byId("browseSortLabel"); if(l) l.textContent=label;
  filterHomeProducts();
}
// Closest-first paging: order the catalogue index by vendor distance, then load full rows a page at a time.
async function nearBrowseLoader(index, wantService, matchingIds, catId, listing){
  const coords=await ensureVendorCoords();
  const allow=matchingIds?new Set(matchingIds):null;
  let list=index.filter(x=>!!x.is_service===wantService&&(!catId||String(x.category_id)===String(catId))&&(!allow||allow.has(x.id)));
  const dist=x=>{const c=coords.get(String(x.vendor_id));return c?haversineKm(buyerLocation.lat,buyerLocation.lng,c.lat,c.lng):Infinity};
  list=list.map(x=>({id:x.id,d:dist(x)})).sort((a,b)=>a.d-b.d);
  let offset=0;
  const keep=p=>listing==="rent"?["rent","both"].includes(p.listing_type):listing==="sale"?["sale","both"].includes(p.listing_type):true;
  const loadMore=async()=>{
    while(offset<list.length){
      const ids=list.slice(offset,offset+BROWSE_GRID_PAGE).map(x=>x.id); offset+=ids.length;
      const rows=(await fetchProductsByIds(ids)).filter(keep);
      if(rows.length) return rows;
    }
    return [];
  };
  return { loadMore, more:()=>offset<list.length };
}
function chooseBrowseListing(value,label){
  const select=byId("filterListing"); if(!select)return;
  select.value=value; syncBrowseFilterLabels();
  byId("browseListingSubmenu")?.classList.add("hidden");
  filterHomeProducts();
}
function chooseBrowseCategory(value,label){
  const select=byId("filterCategory"); if(!select)return;
  select.value=value; syncBrowseFilterLabels();
  const input=byId("filterCategorySearch"); if(input) input.value="";
  filterBrowseCategoryOptions();
  byId("browseCategorySubmenu")?.classList.add("hidden");
  filterHomeProducts();
}
function clearBrowseFilters(){
  const l=byId("filterListing"),c=byId("filterCategory"),s=byId("searchInput");
  if(l)l.value=""; if(c)c.value=""; if(s)s.value=""; window.__browseSort=""; { const sl=byId("browseSortLabel"); if(sl) sl.textContent="Recommended"; }
  const catSearch=byId("filterCategorySearch"); if(catSearch)catSearch.value="";
  syncBrowseFilterLabels(); filterBrowseCategoryOptions(); filterHomeProducts(); toggleBrowseFilters();
}

function filterBrowseCategoryOptions() {
  const input = byId("filterCategorySearch");
  const select = byId("filterCategory");
  const optionsWrap = byId("browseCategoryOptions");
  if (!input || !select || !optionsWrap) return;
  if (!select._allCategoryOptions) select._allCategoryOptions = [...select.options].map(o => ({ value:o.value, label:o.textContent }));
  const q = String(input.value || "").trim().toLowerCase();
  const currentValue = String(select.value || "");
  const filtered = select._allCategoryOptions.filter((o, i) => i === 0 || !q || String(o.label).toLowerCase().includes(q));
  optionsWrap.innerHTML = filtered.slice(1).map(o => `<button type="button" data-value="${esc(o.value)}" data-label="${esc(o.label)}" onclick="chooseBrowseCategory('${String(o.value).replace(/'/g,'\&#39;')}','${String(o.label).replace(/'/g,'\&#39;')}')">${esc(o.label)}</button>`).join("");
  select.value = filtered.some(o => String(o.value) === currentValue) ? currentValue : currentValue && !filtered.some(o=>String(o.value)===currentValue) ? "" : currentValue;
  syncBrowseFilterLabels();
}

let homeFilterGeneration = 0;
// ---------- BROWSE EVERYTHING DATA (light index + 24-at-a-time rows) ----------
const productRowCache = new Map();
async function fetchProductsByIds(ids) {
  const want = [...new Set((ids || []).map(String))];
  if (!want.length) return [];
  const missing = want.filter((id) => !productRowCache.has(id));
  if (missing.length) {
    const { data, error } = await sb.from("products").select(PRODUCT_LIST_SELECT).in("id", missing)
      .eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true);
    if (!error) (data || []).forEach((p) => productRowCache.set(String(p.id), p));
  }
  if (productRowCache.size > 600) [...productRowCache.keys()].slice(0, 200).forEach((k) => productRowCache.delete(k));
  return want.map((id) => productRowCache.get(id)).filter(Boolean);
}
// Campus view: the Home campus bar can narrow Browse to one campus's vendors.
async function loadBrowseIndex(activeSector, activeCategory) {
  const idx = await loadBrowseIndexRaw(activeSector, activeCategory);
  const view = (typeof window.lvViewCampus === "function") ? window.lvViewCampus() : "all";
  if (!Array.isArray(idx) || !view || view === "all") return idx;
  return idx.filter((x) => x.campus_id === view || x.ops_scope === "all" || (x.ops_scope === "multiple" && Array.isArray(x.ops) && x.ops.includes(view)));
}
async function loadBrowseIndexRaw(activeSector, activeCategory) {
  const slot = Math.floor(Date.now() / 600000);
  const key = `levro-browse-idx3:${slot}:${activeSector?.id || "all"}:${activeCategory?.id || "all"}`;
  window.__homeBrowseIdxMem = window.__homeBrowseIdxMem || new Map();
  if (window.__homeBrowseIdxMem.has(key)) return window.__homeBrowseIdxMem.get(key);
  // A category is a subset of the full catalogue index we already hold -- no request needed.
  if (activeCategory && Array.isArray(window.__homeFullIndex)) {
    const subset = deterministicBrowseVisibilityShuffle(window.__homeFullIndex.filter((x) => String(x.category_id) === String(activeCategory.id)), `browse:all`);
    window.__homeBrowseIdxMem.set(key, subset);
    return subset;
  }
  try { const saved = JSON.parse(sessionStorage.getItem(key) || "null"); if (Array.isArray(saved)) { window.__homeBrowseIdxMem.set(key, saved); return saved; } } catch (_) {}
  const rows = [];
  const pageSize = 1000;
  for (let offset = 0; offset < 20000; offset += pageSize) {
    let q = sb.from("products")
      .select(`id, vendor_id, category_id, is_service, category:categories${activeSector ? "!inner" : ""}(sector_id), vendor:vendors!inner(id, campus_id, operating_scope, operating_campuses)`)
      .eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true);
    if (activeSector) q = q.eq("category.sector_id", activeSector.id);
    if (activeCategory) q = q.eq("category_id", activeCategory.id);
    const { data, error } = await q.order("id").range(offset, offset + pageSize - 1);
    if (error) return null;
    rows.push(...(data || []));
    if (!data || data.length < pageSize) break;
  }
  const slim = rows.map((r) => ({ id: r.id, vendor_id: r.vendor_id, campus_id: r.vendor?.campus_id || null, ops_scope: r.vendor?.operating_scope || "one", ops: r.vendor?.operating_campuses || [], category_id: r.category_id, is_service: !!r.is_service, category: { sector_id: r.category?.sector_id || null } }));
  const rotated = deterministicBrowseVisibilityShuffle(slim, `browse:${activeSector?.id || "all"}`);
  window.__homeBrowseIdxMem.set(key, rotated);
  try { Object.keys(sessionStorage).filter((k) => k.startsWith("levro-browse-idx") && k !== key).forEach((k) => sessionStorage.removeItem(k)); sessionStorage.setItem(key, JSON.stringify(rotated)); } catch (_) {}
  return rotated;
}
// Browse Everything renders a page at a time and loads the next one as you
// scroll near the end (the list is already in memory; this keeps the DOM small).
const BROWSE_GRID_PAGE = 24;
let browseGridObserver = null;
function paintBrowseGrid(grid, list) {
  browseGridObserver?.disconnect(); browseGridObserver = null;
  let shown = Math.min(BROWSE_GRID_PAGE, list.length);
  grid.innerHTML = list.slice(0, shown).map(productCardHtml).join("");
  if (shown >= list.length) return;
  if (!("IntersectionObserver" in window)) { grid.insertAdjacentHTML("beforeend", list.slice(shown).map(productCardHtml).join("")); return; }
  const sentinel = document.createElement("div");
  sentinel.className = "browse-sentinel";
  sentinel.style.cssText = "grid-column:1/-1;height:1px";
  grid.appendChild(sentinel);
  const io = new IntersectionObserver((entries) => {
    if (!entries.some((e) => e.isIntersecting)) return;
    if (!sentinel.isConnected) { io.disconnect(); return; }
    const next = list.slice(shown, shown + BROWSE_GRID_PAGE);
    shown += next.length;
    sentinel.insertAdjacentHTML("beforebegin", next.map(productCardHtml).join(""));
    if (shown >= list.length) { io.disconnect(); sentinel.remove(); return; }
    io.unobserve(sentinel); io.observe(sentinel);   // still on screen? load the next page too
  }, { rootMargin: "700px 0px" });
  browseGridObserver = io;
  io.observe(sentinel);
}
// Pages of Browse Everything load on demand: loadMore() resolves to the next rows
// (empty = no more). The old grid is replaced as a whole when the filters change.
function paintBrowsePaged(grid, firstRows, loadMore, hasMore, generation) {
  browseGridObserver?.disconnect(); browseGridObserver = null;
  grid.innerHTML = firstRows.map(productCardHtml).join("");
  if (!hasMore()) return;
  const sentinel = document.createElement("div");
  sentinel.className = "browse-sentinel";
  sentinel.style.cssText = "grid-column:1/-1;height:1px";
  grid.appendChild(sentinel);
  let loading = false;
  const io = new IntersectionObserver(async (entries) => {
    if (loading || !entries.some((e) => e.isIntersecting)) return;
    if (!sentinel.isConnected || generation !== homeFilterGeneration) { io.disconnect(); return; }
    loading = true;
    let next = [];
    try { next = await loadMore(); } catch (_) {}
    loading = false;
    if (!sentinel.isConnected || generation !== homeFilterGeneration) { io.disconnect(); return; }
    if (next.length) sentinel.insertAdjacentHTML("beforebegin", next.map(productCardHtml).join(""));
    if (!hasMore()) { io.disconnect(); sentinel.remove(); return; }
    io.unobserve(sentinel); io.observe(sentinel);
  }, { rootMargin: "700px 0px" });
  browseGridObserver = io;
  io.observe(sentinel);
}
async function filterHomeProducts() {
  const generation = ++homeFilterGeneration;
  const search = byId("searchInput")?.value.trim() || "";
  const listing = byId("filterListing")?.value || "";
  const catId = byId("filterCategory")?.value || "";
  const grid = byId("productGrid");
  if (!grid) return;
  if (homeListingTab === "packages") {
    renderHomePackageTab().catch(() => {});
    return;
  }

  renderHomePackageSearch(search).catch(() => {});
  const wantService = homeListingTab === "services";
  const extraCategory = catId && String(catId) !== String(currentHomeCategoryId || "");

  // Offline / first paint: whatever is already on the device.
  const localCatalog = Array.isArray(window.__homeBrowseCatalog) && window.__homeBrowseCatalog.length
    ? window.__homeBrowseCatalog
    : (getOfflineHomeCache()?.browseProducts || []);
  const localFiltered = offlineFilterProducts(localCatalog, search, listing, extraCategory ? catId : "", currentSectorId)
    .filter(p => wantService ? !!p.is_service : !p.is_service);
  const hasLocalCatalogue = localCatalog.length > 0;
  if (browserLooksOffline()) {
    if (localFiltered.length) paintBrowseGrid(grid, localFiltered);
    else grid.innerHTML = hasLocalCatalogue
      ? `<div class="empty-state">No ${homeListingTab} match these filters.</div>`
      : `<div class="empty-state" style="grid-column:1/-1;"><i class="fa-solid fa-wifi-slash" style="display:block;font-size:1.5rem;margin-bottom:.5rem;"></i>No saved products match these filters while you're offline.</div>`;
    return;
  }

  const index = Array.isArray(window.__homeBrowseIndex) ? window.__homeBrowseIndex : null;
  const plain = !search && !listing && !extraCategory;

  // A) Plain browse: follow the rotated catalogue order, 24 products at a time.
  const nearSort = window.__browseSort === "near" && !!buyerLocation && !!index;
  if (nearSort && plain) {
    const nl = await nearBrowseLoader(index, wantService, null, "", "");
    const firstNear = await nl.loadMore();
    if (generation !== homeFilterGeneration || !byId("productGrid")) return;
    if (!firstNear.length) { grid.innerHTML = `<div class="empty-state">No ${homeListingTab} match these filters.</div>`; return; }
    paintBrowsePaged(grid, firstNear, nl.loadMore, nl.more, generation);
    return;
  }
  if (plain && index) {
    const order = index.filter((x) => !!x.is_service === wantService).map((x) => x.id);
    let offset = 0;
    const loadMore = async () => { const ids = order.slice(offset, offset + BROWSE_GRID_PAGE); offset += ids.length; return fetchProductsByIds(ids); };
    const first = await loadMore();
    if (generation !== homeFilterGeneration || !byId("productGrid")) return;
    if (!first.length) { grid.innerHTML = `<div class="empty-state">No ${homeListingTab} match these filters.</div>`; return; }
    paintBrowsePaged(grid, first, loadMore, () => offset < order.length, generation);
    return;
  }

  // Quick paint from what is on the device while the filtered request runs.
  if (hasLocalCatalogue && localFiltered.length) paintBrowseGrid(grid, localFiltered);

  // B) Text search: the search function returns the matching ids (best match first).
  let matchingIds = null;
  if (search) {
    try {
      const { data: idRows, error: searchError } = await sb.rpc("search_product_ids", { p_query: search });
      if (generation !== homeFilterGeneration || !byId("productGrid")) return;
      if (searchError) throw searchError;
      matchingIds = (idRows || []).map((r) => r.id);
      if (matchingIds.length === 0) {
        if (localFiltered.length) return;
        const fallback = await fetchFallbackProducts();
        if (generation !== homeFilterGeneration) return;
        grid.innerHTML = noResultsWithFallbackHtml(`No product named "${search}" yet - but here's what's available:`, fallback);
        return;
      }
    } catch (err) {
      console.warn("[Levromart] Home product search lookup failed; preserving local browse data:", err);
      return;
    }
  }

  if (nearSort) {
    const nl = await nearBrowseLoader(index, wantService, matchingIds, extraCategory ? catId : "", listing);
    const firstNear = await nl.loadMore();
    if (generation !== homeFilterGeneration || !byId("productGrid")) return;
    if (!firstNear.length) { grid.innerHTML = `<div class="empty-state">No ${homeListingTab} match these filters.</div>`; return; }
    paintBrowsePaged(grid, firstNear, nl.loadMore, nl.more, generation);
    return;
  }
  // C) Filters (and search results): the server does the filtering, a page at a time.
  const buildQuery = (idSlice) => {
    let q = sb.from("products").select(PRODUCT_LIST_SELECT)
      .eq("status", "active").eq("vendor.verification_status", "verified").eq("vendor.is_active", true)
      .eq("is_service", wantService);
    if (idSlice) q = q.in("id", idSlice);
    if (listing === "rent") q = q.in("listing_type", ["rent", "both"]);
    if (listing === "sale") q = q.in("listing_type", ["sale", "both"]);
    if (catId) q = q.eq("category_id", catId);
    else if (currentHomeCategoryId) q = q.eq("category_id", currentHomeCategoryId);
    if (currentSectorId) q = q.eq("category.sector_id", currentSectorId);
    return q;
  };
  let offset = 0, more = true;
  const loadMore = async () => {
    if (matchingIds) {
      // Search results: walk the best-match-first id list a slice at a time.
      while (offset < matchingIds.length) {
        const ids = matchingIds.slice(offset, offset + BROWSE_GRID_PAGE);
        offset += ids.length;
        const { data, error } = await buildQuery(ids).range(0, BROWSE_GRID_PAGE - 1);
        if (error) throw error;
        const rows = (data || []).slice().sort((a, b) => ids.indexOf(a.id) - ids.indexOf(b.id));
        if (rows.length) { more = offset < matchingIds.length; return rows; }
      }
      more = false;
      return [];
    }
    const { data, error } = await buildQuery().order("created_at", { ascending: false }).range(offset, offset + BROWSE_GRID_PAGE - 1);
    if (error) throw error;
    const rows = data || [];
    offset += rows.length;
    more = rows.length >= BROWSE_GRID_PAGE;
    return rows;
  };
  let first;
  try { first = await loadMore(); } catch (err) {
    console.warn("[Levromart] Home browse query failed; preserving local browse data:", err);
    if (!hasLocalCatalogue) {
      const fallback = await fetchFallbackProducts();
      if (generation !== homeFilterGeneration) return;
      grid.innerHTML = noResultsWithFallbackHtml("The marketplace is taking a moment to load - here's what's available:", fallback);
    }
    return;
  }
  if (generation !== homeFilterGeneration || !byId("productGrid")) return;
  if (!first.length) {
    if (localFiltered.length) return;
    const fallback = await fetchFallbackProducts();
    if (generation !== homeFilterGeneration) return;
    grid.innerHTML = noResultsWithFallbackHtml(search ? `No exact match for "${search}" with these filters - but here's what's available:` : "No products match these filters - but here's what's available:", fallback);
    return;
  }
  paintBrowsePaged(grid, first, loadMore, () => more, generation);
}

function hydrateProductVariantIndicatorsInView(){
  // A variety indicator is intentionally tied to multiple listing photos.
  // productCardHtml() already renders this synchronously from p.photos when
  // it has that data; this pass is the backfill for any card rendered
  // without it, using the photo cache populated elsewhere. It sits right
  // next to the price now (icon only, no label) rather than under the
  // removed delivery-summary line.
  const nodes=[...document.querySelectorAll('.product-card-wrap[data-product-id]')];
  if(!nodes.length)return;
  nodes.forEach(node=>{
    const photos=Array.isArray((window.__productPhotoCache||{})[node.dataset.productId])
      ? (window.__productPhotoCache||{})[node.dataset.productId]
      : null;
    const img=node.querySelector('.product-img');
    const photoCount=photos ? photos.length : Number(img?.querySelectorAll('img').length||0);
    const priceEl=node.querySelector('.product-card-compact-price');
    if(!priceEl)return;
    let el=priceEl.querySelector('.product-variety-indicator');
    if(photoCount>1){
      if(!el){el=document.createElement('i');el.className='fa-solid fa-layer-group product-variety-indicator';el.title='Multiple varieties available';el.setAttribute('aria-label','Multiple varieties available');priceEl.appendChild(el);}
    }else if(el)el.remove();
  });
}
function lvInitials(name){
  const w=String(name||"").replace(/[^\p{L}\p{N} ]/gu," ").trim().split(/\s+/).filter(Boolean);
  if(!w.length) return "?";
  return ((w[0][0]||"")+(w.length>1?(w[1][0]||""):(w[0][1]||""))).toUpperCase();
}
function lvInitialsTileHtml(name){
  let h=0; const n=String(name||"Levromart"); for(let i=0;i<n.length;i++) h=(h*31+n.charCodeAt(i))%360;
  return `<span class="img-initials" style="--ih:${h}" aria-label="${esc(n)}">${esc(lvInitials(n))}</span>`;
}
function productCardHtml(p) {
  const img = p.photos?.[0];
  const commissionService = !!p.is_service && p.billing_model !== "monthly";
  try { (window.__productPhotoCache ||= {})[p.id] = Array.isArray(p.photos) ? p.photos : []; } catch (_) {}
  const isFav = favoriteIds.has(p.id);
  const ownListing = isOwnVendorId(p.vendor?.id);
  const canQuickAdd = !ownListing && !p.is_service && (p.listing_type === "sale" || p.listing_type === "both") && profile?.role !== "admin";
  const actionHtml = p.is_service
    ? `<span class="card-service-btn" title="Service listing" aria-label="Service listing"><i class="fa-solid fa-hand-holding-heart"></i></span>`
    : canQuickAdd
      ? `<button type="button" class="card-cart-btn" onclick="quickAddToCart(event,'${p.id}',this,'${p.vendor?.id || ""}')" title="Add to cart" aria-label="Add ${esc(p.name)} to cart"><i class="fa-solid fa-cart-plus"></i></button>`
      : ownListing
        ? `<span class="badge own-listing-badge" title="You can't buy your own listing"><i class="fa-solid fa-store"></i> Your listing</span>`
        : "";
  // Product cards everywhere (trending, browse everything, search, category
  // browse) show only the photo, name and price, plus a quick-add button --
  // no vendor row, availability, delivery summary or comment icon. All of
  // that detail (delivery type/distance, quantity available, payment
  // before/after delivery, etc.) still shows in full on the product detail
  // page once it's opened -- it's just not cluttering the card itself.
  const hasDiscount = p.discount_price != null && Number(p.discount_price) > 0 && Number(p.discount_price) < Number(p.sale_price ?? Infinity);
  const priceHtml = commissionService ? "" : p.sale_price != null
    ? (hasDiscount
        ? `<span class="product-old-price">${naira(p.sale_price)}</span> <span class="product-current-price">${naira(p.discount_price)}</span>`
        : naira(p.sale_price))
    : p.rental_rate != null ? `${naira(p.rental_rate)}/${p.rental_rate_unit}` : "";
  // A product with more than one photo is treated as having varieties (the
  // established proxy this app already uses elsewhere, avoiding a
  // per-card query against product_variants just to show an icon). Icon
  // only, no "Variety" label text -- it just needs to sit next to the price
  // as a quiet signal that there's a choice to make once the card is opened.
  const hasVariety = Array.isArray(p.photos) && p.photos.length > 1;
  const varietyIconHtml = hasVariety ? `<i class="fa-solid fa-layer-group product-variety-indicator" title="Multiple varieties available" aria-label="Multiple varieties available"></i>` : "";
  // A product with no photo of its own falls back to the vendor's logo
  // filling the whole image slot, rather than a bare "No image" icon --
  // every card ends up with an actual picture in it.
  const noImageFallback = p.vendor?.logo_url
    ? `<img src="${esc(p.vendor.logo_url)}" alt="${esc(p.vendor.business_name || "Vendor")}" loading="lazy" decoding="async" draggable="false" onerror="this.outerHTML=lvInitialsTileHtml(this.alt)">`
    : lvInitialsTileHtml(p.vendor?.business_name || p.name);
  // "Buy price" + the flat delivery fee, added up for you, so the number on
  // the card is what you'd actually pay with delivery -- not just the item
  // price with the delivery cost left to discover later. Distance-priced
  // delivery has no fixed number to add here (it depends on where the buyer
  // is), so that case is left off the card rather than showing a guess.
  const cardItemPrice = hasDiscount ? Number(p.discount_price) : Number(p.sale_price);
  const deliveryMode = String(p.delivery_fee_mode ?? p.vendor?.delivery_fee_mode ?? "free").toLowerCase();
  const deliveryFlatFee = Number(p.delivery_fee ?? p.vendor?.delivery_fee ?? 0) || 0;
  // Always render this line, even when it has nothing to show (rental,
  // service, or distance-priced delivery) -- letting it appear only on
  // some cards was exactly what made cards in the same row end up
  // different heights again, the same bug fixed earlier this session for
  // a different reason.
  // Every product card carries this line (free delivery included). Distance-priced delivery depends on where the
  // buyer is, so it shows the item price plus "+ distance fee" rather than guessing a number.
  // One plain figure: item price plus delivery. Distance pricing uses the same km x rate rule as checkout once the
  // buyer's location is known (until then it is just the item price).
  const cardPerKm = Number(p.delivery_fee_per_km ?? p.vendor?.delivery_fee_per_km ?? 0) || 0;
  // null = distance-priced and the buyer's location is not known yet, so no honest total can be shown (the rate is shown instead).
  const cardDeliveryFee = deliveryMode === "free" ? 0
    : deliveryMode === "distance"
      ? (cardPerKm <= 0 ? 0
        : (p.vendor?.lat == null || p.vendor?.lng == null) ? deliveryFlatFee
        : buyerLocation ? distanceDeliveryFee(cardPerKm, haversineKm(buyerLocation.lat, buyerLocation.lng, Number(p.vendor.lat), Number(p.vendor.lng))) : null)
      : deliveryFlatFee;
  let distHtml = "";
  try {
    if (buyerLocation && p.vendor?.lat != null && p.vendor?.lng != null) {
      const km = haversineKm(buyerLocation.lat, buyerLocation.lng, Number(p.vendor.lat), Number(p.vendor.lng));
      if (Number.isFinite(km)) distHtml = `<div class="product-card-dist dt${lvDistTier(km)}" title="${lvDistTitle(km)}"><i class="fa-solid fa-location-dot" aria-hidden="true"></i>${km < 1 ? Math.max(50, Math.round(km * 10) * 100) + " m" : km.toFixed(1) + " km"}</div>`;
    }
  } catch (_) {}
  const totalHtml = (!commissionService && !p.is_service && p.sale_price != null)
    ? (cardDeliveryFee == null
      ? `<div class="product-card-total-line" title="Delivery fee"><i class="fa-solid fa-truck" aria-hidden="true"></i><span class="product-card-total-label">Delivery</span><strong>${naira(cardPerKm)}/km</strong></div>`
      : `<div class="product-card-total-line" title="Total with delivery"><i class="fa-solid fa-truck" aria-hidden="true"></i><span class="product-card-total-label">Total</span><strong>${naira(cardItemPrice + cardDeliveryFee)}</strong></div>`)
    : (p.is_service ? `<div class="product-card-total-line card-svc-cta"><i class="fa-solid fa-comments-dollar" aria-hidden="true"></i><span class="product-card-total-label">Name your price</span><i class="fa-solid fa-chevron-right" aria-hidden="true"></i></div>` : `<div class="product-card-total-line" style="visibility:hidden;">&nbsp;</div>`);
  // The wishlist management page keeps the explicit heart button -- that's
  // the one place removing something is the whole point of being there, and
  // a double-tap-to-remove gesture would be far less discoverable than a
  // button when the user is specifically managing saved items. Every other
  // card (trending, browse, search, category) drops the persistent icon in
  // favor of a double-tap on the photo, Instagram-style.
  const showFavBtn = p._cardContext === "wishlist";
  return `<div class="product-card-wrap product-card-compact" data-product-id="${esc(p.id)}" data-vendor-id="${esc(p.vendor?.id || p.vendor_id || "")}">
    ${showFavBtn ? `<button class="fav-btn ${isFav ? "active" : ""}" onclick="toggleFavorite(event,'${p.id}')" title="Save to wishlist">${isFav ? "<i class='fa-solid fa-heart'></i>" : "<i class='fa-regular fa-heart'></i>"}</button>` : ""}
    <div class="card" style="cursor:pointer;" onclick="${showFavBtn ? `navigate('productDetail',{productId:'${p.id}'})` : `handleProductImageTap(event,'${p.id}')`}">
      <div class="product-img">${img ? `<img src="${esc(lvThumb(img, 280))}" alt="${esc(p.name)}" loading="lazy" decoding="async" draggable="false">` : noImageFallback}${showFavBtn ? "" : `<span class="product-wish-bounce"><i class="fa-solid fa-heart"></i></span>`}</div>
      <h4><span class="pc-title-row"><span class="pc-vlogo-wrap">${p.vendor?.logo_url ? `<img class="pc-vlogo" src="${esc(p.vendor.logo_url)}" alt="" loading="lazy" decoding="async" draggable="false">` : `<span class="pc-vlogo pc-vlogo-txt">${esc(String(p.vendor?.business_name || "?").trim().charAt(0).toUpperCase())}</span>`}</span><span class="pc-name">${esc(p.name)}</span></span></h4>
      <div class="product-card-compact-footer">
        ${priceHtml ? `<span class="product-card-compact-price">${priceHtml}${varietyIconHtml}</span>` : "<span></span>"}
      </div>
      <div class="product-card-meta">${commissionService ? `<span class="card-svc-tag"><i class="fa-solid fa-handshake"></i> Negotiable</span>` : (distHtml || "<span></span>")}${actionHtml}</div>
      ${totalHtml}
    </div>
  </div>`;
}
// Double-tap on a card's photo toggles the wishlist instead of a
// persistent heart button (the button remains on the Wishlist page
// itself, where removing is the whole point of being there). A single
// tap still opens the product -- it just waits a beat to see whether a
// second tap follows before committing to navigation, the same tradeoff
// every double-tap-to-like gesture makes.
const __productImageTapState = new Map();
function handleProductImageTap(evt, productId) {
  // Buttons inside the card (add to cart, etc.) keep their own behaviour.
  if (evt.target?.closest?.("button, a, .card-cart-btn")) return;
  evt.stopPropagation();
  const now = Date.now();
  const DOUBLE_TAP_MS = 320;
  const state = __productImageTapState.get(productId);
  if (state?.lastTap && now - state.lastTap < DOUBLE_TAP_MS) {
    clearTimeout(state.timer);
    __productImageTapState.delete(productId);
    toggleFavoriteViaDoubleTap(evt.currentTarget, productId);
    return;
  }
  const timer = setTimeout(() => {
    __productImageTapState.delete(productId);
    navigate("productDetail", { productId });
  }, DOUBLE_TAP_MS);
  __productImageTapState.set(productId, { lastTap: now, timer });
}
async function toggleFavoriteViaDoubleTap(imgContainer, productId) {
  if (!session) { showLogin(); return; }
  if (favoriteMutations.has(productId)) return;
  favoriteMutations.add(productId);
  const wasFav = favoriteIds.has(productId);
  // Play the heart the instant the double tap is detected, not after the
  // network round trip -- waiting for that first meant the animation
  // showed up hundreds of milliseconds (or more, on a slow connection)
  // after the tap, by which point it read as "nothing happened" next to
  // the browser's instant tap-highlight flash. Roll back quietly on
  // failure instead.
  if (wasFav) favoriteIds.delete(productId); else favoriteIds.add(productId);
  playProductWishBounce(imgContainer, !wasFav);
  // The bounce animation alone wasn't a reliable enough confirmation (easy
  // to miss, or silently not render) -- a toast says outright what just
  // happened regardless of whether the animation is visible.
  showToast(wasFav ? "Removed from wishlist." : "Added to your wishlist \u2764", "success");
  try {
    const { error } = wasFav
      ? await sb.from("favorites").delete().eq("buyer_id", session.user.id).eq("product_id", productId)
      : await sb.from("favorites").insert({ buyer_id: session.user.id, product_id: productId });
    if (error) throw error;
    await hydrateProductLikeCountsInView();
  } catch (err) {
    if (wasFav) favoriteIds.add(productId); else favoriteIds.delete(productId);
    showToast(err.message || "Could not update wishlist.", "error");
  } finally {
    favoriteMutations.delete(productId);
  }
}
function playProductWishBounce(imgContainer, added) {
  const bounce = imgContainer?.querySelector?.(".product-wish-bounce");
  if (!bounce) return;
  bounce.querySelector("i").className = added ? "fa-solid fa-heart" : "fa-regular fa-heart";
  bounce.classList.remove("added", "removed");
  void bounce.offsetWidth;
  bounce.classList.add(added ? "added" : "removed");
}

// Color-codes the rating itself (not just a flat badge) so a strong vendor
// literally reads as "green" and a weak one as "red" at a glance, scanning
// down a list of cards - matches the 1-5 star scale users already know.
function ratingBadgeClass(rating) {
  const r = Number(rating);
  return "rating-gold";
}
function vendorDistanceKm(v){
  const values=[buyerLocation?.lat,buyerLocation?.lng,v?.lat,v?.lng];if(values.some(x=>x==null||x===''||!Number.isFinite(Number(x))))return null;
  const [a,b,c,d]=values.map(Number);if(Math.abs(a)>90||Math.abs(c)>90||Math.abs(b)>180||Math.abs(d)>180)return null;
  return haversineKm(a,b,c,d);
}
function vendorDistanceHtml(v){const km=vendorDistanceKm(v);return km==null?'':`<span class="vendor-distance dt${lvDistTier(km)}"><i class="fa-solid fa-location-dot"></i> ${km<1?Math.round(km*1000)+' m':km.toFixed(1)+' km'} away</span>`;}
function storefrontDistanceHtml(v){const km=vendorDistanceKm(v);if(km==null)return '';const label=km<1?Math.round(km*1000)+' m':km.toFixed(1)+' km';return `<button type="button" class="storefront-distance-link dt${lvDistTier(km)}" onclick="event.stopPropagation();openVendorDistanceMap('${esc(v?.id||'')}')" title="View route to this vendor on the map" aria-label="${esc(label)} away. View route on map"><i class="fa-solid fa-route"></i> ${esc(label)} away</button>`;}
function vendorCardHtml(v) {
  const name = v?.business_name || "Vendor";
  const avatar = v?.logo_url || v?.user_avatar_url || "";
  const sectorName = v?.sector_name || v?.sector?.name || (Array.isArray(sectors) ? sectors.find(sec => String(sec.id) === String(v?.sector_id))?.name : "") || "";
  const followerCount = Number(v?.follower_count || 0);
  return `<div class="vendor-card homepage-vendor-card" onclick="navigate('storefront',{vendorId:'${esc(v?.id || "")}'});" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();navigate('storefront',{vendorId:'${esc(v?.id || "")}'});}">
    ${avatar ? profileAvatarHtml(avatar, name, "3.05rem", { extraClass: "vendor-home-avatar", lightbox: false, stableKey: v?.id || name }) : avatarFallbackHtml(name, "3.05rem", "vendor-home-avatar vendor-home-avatar-fallback", name)}
    <div class="vendor-home-copy">
      <strong>${esc(name)} <i class="fa-solid fa-circle-check vendor-inline-verified" aria-label="Verified vendor" title="Verified vendor"></i></strong>
      <span class="vendor-home-city"><i class="fa-solid fa-location-dot"></i> ${esc(v?.city || "Online")}</span>${vendorDistanceHtml(v)}
      <div class="vendor-home-meta"><span class="badge success"><i class='fa-solid fa-circle-check'></i> Verified</span><span class="badge ${ratingBadgeClass(Number(v?.avg_rating ?? 0))}"><i class="fa-solid fa-star"></i> ${Number(v?.avg_rating ?? 0).toFixed(1)} · ${Number(v?.review_count ?? 0)} reviews</span></div>
      <span class="vendor-home-known"><i class="fa-solid fa-layer-group"></i> ${esc(sectorName || "Sector not listed")}</span>
      <div class="vendor-card-footer"><span class="badge vendor-follower-badge"><i class="fa-solid fa-user-group"></i> <span class="vendor-follower-count">${followerCount.toLocaleString()}</span> follower${followerCount===1?'':'s'}</span><span class="vendor-home-storefront-label">View storefront <i class="fa-solid fa-arrow-right"></i></span></div>
    </div>
  </div>`;
}

const favoriteMutations=new Set();
async function toggleFavorite(evt,productId){
  evt.stopPropagation();if(!session){showLogin();return;}if(favoriteMutations.has(productId))return;
  favoriteMutations.add(productId);const btn=evt.currentTarget;btn.disabled=true;
  try{const old=favoriteIds.has(productId),{error}=old?await sb.from('favorites').delete().eq('buyer_id',session.user.id).eq('product_id',productId):await sb.from('favorites').insert({buyer_id:session.user.id,product_id:productId});if(error)throw error;
    if(old)favoriteIds.delete(productId);else favoriteIds.add(productId);
    btn.innerHTML=old?"<i class='fa-regular fa-heart'></i>":"<i class='fa-solid fa-heart'></i>";btn.classList.toggle('active',!old);await hydrateProductLikeCountsInView();
  }catch(err){showToast(err.message||'Could not update like.','error');}finally{favoriteMutations.delete(productId);btn.disabled=false;}
}
// ---------- WISHLIST ----------
async function renderWishlist() {
  if (!session) return '<div class="empty-state">Log in to save items to your wishlist.</div>';
  const [{ data: favs }, { data: packageFavs }] = await Promise.all([
    sb.from("favorites").select("product:products(id, name, listing_type, sale_price, rental_rate, rental_rate_unit, photos, quantity_available, condition, is_service, service_price_unit, status, vendor:vendors(id, business_name, verification_status, is_active, logo_url))").eq("buyer_id", session.user.id).order("created_at", { ascending: false }),
    sb.from("package_favorites").select("package:vendor_packages(id, vendor_id, name, description, price, photos, created_at, status, vendor:vendors!inner(id,business_name,logo_url,delivery_fee,verification_status,is_active), items:package_items(quantity, product:products(id,name,photos))").eq("buyer_id", session.user.id).order("created_at", { ascending: false })
  ]);
  const products = (favs || []).map((f) => f.product).filter((p) => p && p.status === "active" && p.vendor?.verification_status === "verified" && p.vendor?.is_active);
  const packages = (packageFavs || []).map((f) => f.package).filter((p) => p && p.status === "active" && p.vendor?.verification_status === "verified" && p.vendor?.is_active);
  let html = `<h2><i class='fa-solid fa-heart'></i> Your Wishlist</h2>`;
  if (products.length) html += `<h3 class="section-title"><i class="fa-solid fa-box"></i> Products</h3><div class="grid">${products.map((p) => productCardHtml({ ...p, _cardContext: "wishlist" })).join("")}</div>`;
  if (packages.length) html += `<h3 class="section-title"><i class="fa-solid fa-boxes-stacked"></i> Packages</h3><div class="grid">${packages.map((p) => packageCardHtml(p, p.vendor?.delivery_fee)).join("")}</div>`;
  if (!products.length && !packages.length) html += `<div class="empty-state">Nothing saved yet. Tap the <i class='fa-regular fa-heart'></i> on a product or package to save it here.</div>`;
  return html;
}

async function renderCustomerFollowing(){
  if(!session?.user?.id || profile?.role==='admin') return '<div class="empty-state">This page is available for customer accounts.</div>';
  try{
    const {data,error}=await sb.from('vendor_follows').select('vendor:vendors!inner(id,business_name,logo_url,cover_image_url,bio,city,avg_rating,review_count,verification_status,is_active,sector_id)').eq('follower_id',session.user.id).order('created_at',{ascending:false});
    if(error) throw error;
    const rows=(data||[]).map(r=>r.vendor).filter(v=>v && v.verification_status==='verified' && v.is_active);
    let html=`<div class="customer-following-page"><div class="customer-following-head"><button type="button" class="icon-btn" onclick="navigate('home')" aria-label="Back"><i class="fa-solid fa-arrow-left"></i></button><div><h2 style="margin:0;"><i class="fa-solid fa-user-group"></i> Vendors you follow</h2><p class="muted" style="margin:.25rem 0 0;">Your followed vendors and their storefronts.</p></div></div>`;
    if(!rows.length) html+=`<div class="empty-state"><i class="fa-solid fa-user-group" style="font-size:1.7rem;display:block;margin-bottom:.6rem;"></i><strong>You aren't following any vendors yet.</strong><p class="muted">Follow a vendor from their storefront and they will appear here.</p><button type="button" class="btn" onclick="navigate('vendors')">Explore vendors</button></div>`;
    else html+=`<label class="lm-fol-search"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input type="search" placeholder="Search vendors you follow…" oninput="lmFilterFollowing(this.value)" autocomplete="off"></label><div class="customer-following-grid">${rows.map(v=>`<button type="button" class="customer-following-card" onclick="navigate('storefront',{vendorId:'${esc(v.id)}'})"><div class="customer-following-avatar">${v.logo_url?`<img src="${esc(v.logo_url)}" alt="${esc(v.business_name||'Vendor')}" loading="lazy">`:`<span>${esc(String(v.business_name||'V').trim().charAt(0).toUpperCase())}</span>`}</div><div class="customer-following-copy"><strong>${esc(v.business_name||'Vendor')}</strong><span>${esc(v.city||'Online')}</span><span>★ ${Number(v.avg_rating||0).toFixed(1)} · ${Number(v.review_count||0)} reviews</span></div><i class="fa-solid fa-chevron-right"></i></button>`).join('')}</div>`;
    html+='</div>'; return html;
  }catch(e){console.error('[Levromart] Customer following load failed:',e);return `<div class="empty-state">Could not load the vendors you follow. <button type="button" class="btn btn-outline" onclick="navigate('customerFollowing',{},false)">Try again</button></div>`;}
}

// The vendor side of the same relationship: who follows THIS shop, not
// which shops the current account follows.
async function renderVendorFollowers(){
  if(!session || profile?.role==='admin' || (profile?.role!=='vendor' && !vendor)) return '<div class="empty-state">Access denied.</div>';
  const { data: v } = await sb.from("vendors").select("id,business_name").eq("user_id", session.user.id).is("deleted_at", null).maybeSingle();
  if (!v) { navigate("vendorApply"); return '<p class="muted">Redirecting…</p>'; }
  let html=`<div class="customer-following-page"><div class="customer-following-head"><button type="button" class="icon-btn" onclick="navigate('vendorDashboard')" aria-label="Back"><i class="fa-solid fa-arrow-left"></i></button><div><h2 style="margin:0;"><i class="fa-solid fa-user-group"></i> Your followers</h2><p class="muted" style="margin:.25rem 0 0;">People following ${esc(v.business_name||"your shop")}.</p></div></div>`;
  try{
    const { data, error } = await sb.rpc("get_vendor_followers", { p_vendor_id: v.id });
    if (error) throw error;
    const rows = data||[];
    if(!rows.length){
      html+=`<div class="empty-state"><i class="fa-solid fa-user-group" style="font-size:1.7rem;display:block;margin-bottom:.6rem;"></i><strong>No followers yet.</strong><p class="muted">Customers who follow your shop will show up here.</p></div>`;
    } else {
      html+=`<div class="vendor-followers-list">${rows.map(r=>{
        const name=r.name||"Levromart user";
        const when=r.followed_at?new Date(r.followed_at).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):"";
        return `<div class="vendor-follower-row">${profileAvatarHtml(r.avatar_url,name,"2.6rem")}<div class="vendor-follower-copy"><strong>${esc(name)}</strong>${when?`<span class="muted">Following since ${esc(when)}</span>`:""}</div></div>`;
      }).join("")}</div>`;
    }
  }catch(e){
    console.error('[Levromart] Vendor followers load failed:',e);
    html+=`<div class="empty-state">Could not load your followers. <button type="button" class="btn btn-outline" onclick="navigate('vendorFollowers',{},false)">Try again</button></div>`;
  }
  html+='</div>'; return html;
}


/* ---- Followers page: tabs (All / Vendors / Customers), search, connection tags ---- */
window.__fp = { rows: [], tab: "all", q: "" };
async function renderVendorFollowersPage() {
  if (!session || profile?.role === "admin") return '<div class="empty-state">Access denied.</div>';
  const { data: v } = await sb.from("vendors").select("id,business_name").eq("user_id", session.user.id).is("deleted_at", null).maybeSingle();
  if (!v) { navigate("vendorApply"); return '<p class="muted">Redirecting…</p>'; }
  window.__fp = { rows: [], tab: "all", q: "", vendorId: v.id };
  setTimeout(fpLoad, 0);
  return `<div class="fp-page">
    <div class="fp-head"><button type="button" class="icon-btn" onclick="navigate('vendorDashboard')" aria-label="Back"><i class="fa-solid fa-arrow-left"></i></button><h2>Followers</h2><span class="fp-count" id="fpCount"></span></div>
    <label class="fp-search"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input id="fpSearch" type="search" placeholder="Search followers…" autocomplete="off" oninput="fpSearch(this.value)"></label>
    <div class="fp-tabs" id="fpTabs" role="tablist"></div>
    <div id="fpList" class="fp-list">${'<div class="lb-skel"></div>'.repeat(4)}</div>
  </div>`;
}
async function fpLoad() {
  const box = byId("fpList"); if (!box) return;
  try {
    const { data, error } = await sb.rpc("get_vendor_followers_v2", { p_vendor_id: window.__fp.vendorId });
    if (error) throw error;
    window.__fp.rows = data || [];
    fpRender();
  } catch (e) {
    box.innerHTML = '<div class="empty-state">Could not load your followers. <button type="button" class="btn btn-outline" onclick="fpLoad()">Try again</button></div>';
  }
}
function fpSearch(q) { window.__fp.q = String(q || "").trim().toLowerCase(); fpRender(); }
function fpTab(t) { window.__fp.tab = t; fpRender(); }
function fpTag(r) {
  if (r.link_level === 1) return '<span class="fn-tag fn-following"><i class="fa-solid fa-check"></i> You follow them</span>';
  if (r.link_level === 2) return `<span class="fn-tag fn-mutual"><i class="fa-solid fa-link"></i> Mutual${r.via_name ? ` · via ${esc(r.via_name)}` : ""}</span>`;
  if (r.link_level === 3) return `<span class="fn-tag fn-wide"><i class="fa-solid fa-diagram-project"></i> 3rd connection${r.via_name ? ` · via ${esc(r.via_name)}` : ""}</span>`;
  return "";
}
function fpRender() {
  const { rows, tab, q } = window.__fp;
  const vend = rows.filter((r) => r.is_vendor), cust = rows.filter((r) => !r.is_vendor);
  const tabs = byId("fpTabs");
  if (tabs) tabs.innerHTML = [["all", "All", rows.length], ["vendors", "Vendors", vend.length], ["customers", "Customers", cust.length]].map(([k, l, n]) => `<button type="button" role="tab" class="fp-tab${tab === k ? " active" : ""}" onclick="fpTab('${k}')">${l} <b>${n}</b></button>`).join("");
  const c = byId("fpCount"); if (c) c.textContent = rows.length ? `${rows.length} total` : "";
  let list = tab === "vendors" ? vend : tab === "customers" ? cust : rows;
  if (q) list = list.filter((r) => `${r.name || ""} ${r.business_name || ""} ${r.city || ""} ${r.sector_name || ""}`.toLowerCase().includes(q));
  const box = byId("fpList"); if (!box) return;
  if (!list.length) { box.innerHTML = `<div class="empty-state"><i class="fa-solid fa-user-group" style="font-size:1.6rem;display:block;margin-bottom:.5rem"></i><strong>${q ? "No one matches your search" : tab === "vendors" ? "No vendor followers yet" : tab === "customers" ? "No customer followers yet" : "No followers yet"}</strong></div>`; return; }
  box.innerHTML = list.map((r) => {
    const name = r.name || "Levromart user";
    const when = r.followed_at ? new Date(r.followed_at).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" }) : "";
    const av = profileAvatarHtml(r.avatar_url, name, "3rem");
    const open = r.is_vendor && r.vendor_id ? ` onclick="navigate('storefront',{vendorId:'${esc(r.vendor_id)}'})" role="link" tabindex="0"` : "";
    const sub = r.is_vendor ? [r.sector_name, r.city].filter(Boolean).join(" · ") : "Customer";
    return `<div class="fp-row${r.is_vendor ? " clickable" : ""}"${open}>${av}<div class="fp-copy"><strong>${esc(name)}</strong><span class="muted">${esc(sub)}${when ? ` · since ${esc(when)}` : ""}</span>${fpTag(r)}</div>${r.is_vendor ? '<i class="fa-solid fa-chevron-right fp-go"></i>' : ""}</div>`;
  }).join("");
}
// ---------- FOLLOWER NETWORK (vendors only) ----------
// Tapping "N followers" opens the vendors that follow this shop (customers are never listed). Each row says how
// the viewer is connected: Following (you follow them), Mutual (a vendor you follow follows them) or
// Wider network (reached through two steps), so people can grow their circle by following vendors they may know.
function openFollowerNetwork(vendorId) {
  const id = vendorId || currentViewParams?.vendorId;
  if (id) navigate("vendorFollowerNetwork", { vendorId: id });
}
function followerNetworkTagHtml(r) {
  if (r.is_me) return `<span class="fn-tag fn-me">You</span>`;
  if (r.link_level === 1) return `<span class="fn-tag fn-following"><i class="fa-solid fa-check"></i> Following</span>`;
  if (r.link_level === 2) return `<span class="fn-tag fn-mutual"><i class="fa-solid fa-link"></i> Mutual${r.via_name ? ` · via ${esc(r.via_name)}` : ""}</span>`;
  if (r.link_level === 3) return `<span class="fn-tag fn-wide"><i class="fa-solid fa-diagram-project"></i> Wider network${r.via_name ? ` · via ${esc(r.via_name)}` : ""}</span>`;
  return "";
}
async function renderVendorFollowerNetwork(vendorId) {
  if (!vendorId) return '<div class="empty-state">Vendor not found.</div>';
  const [{ data: v }, netRes] = await Promise.all([
    sb.from("vendors").select("id,business_name").eq("id", vendorId).maybeSingle(),
    sb.rpc("get_vendor_follower_network", { p_vendor_id: vendorId }),
  ]);
  const rows = netRes?.data || [];
  const head = `<div class="fn-head"><button type="button" class="icon-btn" onclick="history.length>1?history.back():navigate('vendors')" aria-label="Back"><i class="fa-solid fa-arrow-left"></i></button><div><h2>Followers</h2><p class="muted">Vendors following ${esc(v?.business_name || "this shop")}</p></div></div>`;
  if (netRes?.error) return `<div class="fn-page">${head}<div class="empty-state">Could not load followers. <button type="button" class="btn btn-outline" onclick="navigate('vendorFollowerNetwork',{vendorId:'${esc(vendorId)}'},false)">Try again</button></div></div>`;
  if (!rows.length) return `<div class="fn-page">${head}<div class="empty-state"><i class="fa-solid fa-user-group" style="font-size:1.7rem;display:block;margin-bottom:.6rem;"></i><strong>No vendor followers yet.</strong><p class="muted">Only vendors who follow this shop are shown here.</p></div></div>`;
  const recent = window.__vendorCardFollowRecent;
  const list = rows.map((r) => {
    const id = String(r.vendor_id);
    const rc = recent?.get(id);
    const following = rc && Date.now() - rc.at < 15000 ? !!rc.following : (r.is_following || !!(session && window.followedVendorSet?.().has(id)));
    const logo = r.logo_url ? `<img src="${esc(r.logo_url)}" alt="" class="fn-avatar" loading="lazy" decoding="async">` : avatarFallbackHtml(r.business_name || "Vendor", "3.2rem", "fn-avatar", r.business_name || "Vendor");
    return `<div class="fn-row" onclick="navigate('storefront',{vendorId:'${esc(id)}'})" role="link" tabindex="0">
      ${logo}
      <div class="fn-copy"><strong>${esc(r.business_name || "Vendor")}</strong><span class="muted">${esc([r.sector_name, r.city].filter(Boolean).join(" · ") || "Vendor")}</span>${followerNetworkTagHtml(r)}</div>
      ${r.is_me ? "" : `<button type="button" class="vendor-card-follow-btn fn-follow${following ? " following" : ""}" data-vendor-id="${esc(id)}" onclick="event.stopPropagation();toggleVendorCardFollow('${esc(id)}',event)">${following ? "Following" : "Follow"}</button>`}
    </div>`;
  }).join("");
  return `<div class="fn-page">${head}<div class="fn-list">${list}</div></div>`;
}

// ---------- CART (buy-and-sale items only, grouped by vendor; add/remove actions stay on the current page) ----------
//
// vendor group checks out as its own order, same reasoning as the
// single-vendor-per-checkout recommendation: one Paystack charge per
// vendor keeps the existing per-order payment/payout machinery untouched
// instead of inventing a split-charge system) ----------
function cartItemRowHtml(it) {
  const p = it.product;
  const variant = it.variant || null;
  const effectivePrice = Number(variant?.discount_price ?? variant?.sale_price ?? p.discount_price ?? p.sale_price ?? 0);
  const img = variant?.photo_url || (p.photos && p.photos[0]);
  return `<div class="cart-item">
    ${img ? `<img class="cart-item-img" src="${esc(lvThumb(img, 120))}" alt="" loading="lazy" decoding="async" />` : `<span class="cart-item-img cart-item-img-empty"><i class="fa-solid fa-box"></i></span>`}
    <div class="cart-item-main">
      <strong class="cart-item-name">${esc(p.name)}</strong>
      ${variant ? `<span class="cart-item-variant">${esc(variant.name)}</span>` : ""}
      <span class="cart-item-price">${naira(effectivePrice)} <small>each</small></span>
      <div class="cart-item-controls">
        <div class="cart-qty" role="group" aria-label="Quantity">
          <button type="button" aria-label="Decrease quantity" onclick="updateCartQty('${it.id}',${it.quantity - 1})" ${it.quantity <= 1 ? "disabled" : ""}><i class="fa-solid fa-minus"></i></button>
          <span aria-live="polite">${it.quantity}</span>
          <button type="button" aria-label="Increase quantity" onclick="updateCartQty('${it.id}',${it.quantity + 1})"><i class="fa-solid fa-plus"></i></button>
        </div>
        <button type="button" class="cart-remove" title="Remove" aria-label="Remove ${esc(p.name)} from cart" onclick="removeFromCart('${it.id}')"><i class="fa-solid fa-trash"></i></button>
      </div>
    </div>
  </div>`;
}
async function renderCart() {
  if (!session) return '<div class="empty-state">Log in to see your cart.</div>';
  if (profile?.role === "admin") return '<div class="empty-state">Admin accounts can\'t make purchases on Levromart.</div>';

  const cartResult = await withRouteTimeout(
    sb.from("cart_items")
      .select("id, variant_id, quantity, created_at, variant:product_variants(*), product:products(id, name, sale_price, discount_price, photos, quantity_available, status, delivery_fee, delivery_fee_mode, delivery_fee_per_km, vendor:vendors(id, business_name, previous_business_name, name_changed_at, is_active, verification_status, delivery_fee, delivery_fee_mode, delivery_fee_per_km, lat, lng))")
      .eq("buyer_id", session.user.id)
      .order("created_at", { ascending: true }),
    8000,
    { data: null, error: new Error("Your cart is taking too long to load. Please try again.") }
  );
  const { data: items, error } = cartResult || { data: null, error: new Error("Your cart could not be loaded.") };
  if (error) return `<h2 class="cart-page-title"><i class="fa-solid fa-cart-shopping"></i> Your Cart</h2>${errorStateHtml(error)}<button class="btn btn-outline" onclick="navigate('cart',{},false)"><i class="fa-solid fa-rotate-right"></i> Try again</button>`;

  const cartHead = (n) => `<div class="cart-head"><button type="button" class="cart-back" onclick="history.length>1?history.back():navigate('home')" aria-label="Back"><i class="fa-solid fa-arrow-left"></i></button><h2 class="cart-page-title"><i class="fa-solid fa-cart-shopping cart-title-ico"></i> My Cart${n ? ` <span class="cart-count">(${n})</span>` : ""}</h2>${n ? `<button type="button" class="cart-ico cart-checkall" onclick="openCheckoutAllSheet()" aria-label="Checkout all" title="Checkout all"><i class="fa-solid fa-bag-shopping"></i></button><button type="button" class="cart-ico cart-clear" onclick="openClearCartSheet()" aria-label="Clear cart" title="Clear cart"><i class="fa-solid fa-trash-can"></i></button>` : ""}</div>`;
  let html = "";
  if (!items || items.length === 0) {
    return `<div class="cart-page">${cartHead(0)}<div class="vd-empty"><span class="vd-empty-ico"><i class="fa-solid fa-cart-shopping"></i></span><strong>Your cart is empty</strong><p>Add items from any product page, or tell Levi what you want and it'll add them for you.</p><button type="button" class="vl-add" onclick="navigate('home')"><i class="fa-solid fa-bag-shopping"></i> Start shopping</button></div></div>`;
  }

  const valid = items.filter((it) => it.product && it.product.status === "active" && it.product.vendor?.verification_status === "verified" && it.product.vendor?.is_active);
  const ownItems = valid.filter((it) => isOwnVendorId(it.product.vendor?.id));
  if (ownItems.length) {
    // Clean up any legacy/self-added cart rows created before the current
    // self-purchase guard. New self-items are blocked by both the UI and DB
    // trigger, so this only removes stale rows that should never have been
    // purchasable in the first place.
    await sb.from("cart_items").delete().in("id", ownItems.map((it) => it.id));
  }
  const purchasable = valid.filter((it) => !ownItems.includes(it));
  const stale = items.filter((it) => !purchasable.includes(it));

  const byVendor = new Map();
  purchasable.forEach((it) => {
    const vId = String(it.product.vendor.id);
    if (!byVendor.has(vId)) byVendor.set(vId, { vendor: it.product.vendor, items: [] });
    byVendor.get(vId).items.push(it);
  });
  window.__cartByVendor = byVendor;

  [...byVendor.values()].forEach(({ vendor: v, items: vItems }) => {
    const subtotal = vItems.reduce((s, it) => s + Number(it.variant?.discount_price ?? it.variant?.sale_price ?? it.product.discount_price ?? it.product.sale_price ?? 0) * it.quantity, 0);
    const ownCartVendor = isOwnVendorId(v.id);
    // The server adds each product's OWN delivery fee (create_cart_order), so the cart does too.
    const feeLines = vItems.map((it) => ({ name: it.product.name, mode: String(it.product.delivery_fee_mode || "free").toLowerCase(), fee: Number(it.product.delivery_fee) || 0, perKm: Number(it.product.delivery_fee_per_km) || 0 }));
    const cartFlatFee = feeLines.reduce((n, l) => n + (l.mode === "flat" ? l.fee : 0), 0);
    const cartDistanceLine = feeLines.find((l) => l.mode === "distance" && l.perKm > 0);
    const deliveryHtml = deliveryFieldsHtml(`cart-${v.id}`, cartFlatFee, v.lat, v.lng, cartDistanceLine ? "distance" : "flat", cartDistanceLine ? cartDistanceLine.perKm : 0, "", subtotal)
      .replace(`id="cart-${v.id}DeliveryFields"`, `id="cart-${v.id}DeliveryFields" data-fee-lines="${JSON.stringify(feeLines).replace(/"/g, "&quot;")}"`);
    // The live item / delivery / total breakdown lives in its own Order summary card.
    const breakdownRe = new RegExp(`<div id="cart-${v.id}PriceBreakdown"[^>]*></div>`);
    const deliveryNoBreakdown = deliveryHtml.replace(breakdownRe, "");
    const itemCount = vItems.reduce((n, it) => n + it.quantity, 0);
    html += `<section class="cart-vendor-card ${ownCartVendor ? "own-cart-vendor" : ""}" data-cart-vendor="${esc(v.id)}">
      <a href="#" class="cart-vendor-head" onclick="navigate('storefront',{vendorId:'${v.id}'});return false;"><span class="cart-vh-ico"><i class="fa-solid fa-store cart-ico-vendor"></i></span><span class="cart-vh-txt"><b>${vendorNameWithFormerly(v)}</b><small>${vItems.length} item${vItems.length === 1 ? "" : "s"} from this store</small></span><span class="cart-vh-btn">View Store <i class="fa-solid fa-chevron-right"></i></span></a>
      ${ownCartVendor ? `<p class="error-text" style="margin:.5rem .9rem;"><i class="fa-solid fa-ban"></i> Your own products can't be purchased from your shop.</p>` : ""}
      <div class="cart-items">${vItems.map(cartItemRowHtml).join("")}</div>
    </section>
    <section class="cart-card cart-summary"><div class="cart-card-head"><h3><i class="fa-solid fa-receipt cart-ico-sum"></i> Order summary</h3><strong>${naira(subtotal)}</strong></div>
      <div class="cart-summary-row"><span>Subtotal (${itemCount} item${itemCount === 1 ? "" : "s"})</span><strong>${naira(subtotal)}</strong></div>
      <div id="cart-${v.id}PriceBreakdown" class="price-breakdown-table" aria-live="polite"></div></section>
    <section class="cart-card cart-delivery"><h3><i class="fa-solid fa-truck-fast cart-ico-del"></i> Delivery option</h3>${deliveryNoBreakdown}</section>
    <section class="cart-card cart-note"><label for="cartNote-${v.id}">Note for the vendor <span>(optional)</span></label>
      <textarea id="cartNote-${v.id}" rows="3" maxlength="200" placeholder="e.g. I'd like the blue one, or a size 42" oninput="this.nextElementSibling.textContent=this.value.length+'/200'"></textarea><small class="cart-note-count">0/200</small></section>
    ${ownCartVendor ? `<button class="btn btn-outline" style="width:100%;" disabled title="You can't purchase from your own shop"><i class="fa-solid fa-ban"></i> Checkout unavailable</button>` : `<button type="button" class="cart-checkout" onclick="checkoutCartVendor('${v.id}')"><i class="fa-solid fa-bag-shopping"></i><span class="cart-checkout-label">Checkout · ${esc(v.business_name)}</span><b id="cart-${v.id}CheckoutTotal">${naira(subtotal)}</b></button>`}
    <p id="cartError-${v.id}" class="error-text hidden"></p>`;
  });

  if (ownItems.length) {
    html += `<p class="muted" style="font-size:0.85rem;"><i class="fa-solid fa-ban"></i> ${ownItems.length} self-owned cart item${ownItems.length === 1 ? " was" : "s were"} removed because vendors can't purchase from their own shop.</p>`;
  }
  if (stale.length && stale.length !== ownItems.length) {
    window.__staleCartIds = stale.filter((it) => !ownItems.includes(it)).map((it) => it.id);
    html += `<p class="muted" style="font-size:0.85rem;"><i class="fa-solid fa-circle-info"></i> ${stale.length - ownItems.length} item${stale.length - ownItems.length === 1 ? "" : "s"} in your cart ${stale.length - ownItems.length === 1 ? "is" : "are"} no longer available and won't be included at checkout. <a href="#" onclick="clearStaleCartItems();return false;">Remove ${stale.length - ownItems.length === 1 ? "it" : "them"}</a>.</p>`;
  }
  return `<div class="cart-page">${cartHead([...byVendor.values()].reduce((n, g) => n + g.items.length, 0))}${html}</div>`;
}
function openClearCartSheet() {
  if (byId("clearCartSheet")) return;
  const wrap = document.createElement("div");
  wrap.id = "clearCartSheet";
  wrap.className = "cc-backdrop";
  wrap.innerHTML = `<div class="cc-sheet" role="dialog" aria-modal="true" aria-labelledby="ccTitle"><button type="button" class="cc-x" aria-label="Close" data-cc="close"><i class="fa-solid fa-xmark"></i></button>
    <span class="cc-ico"><i class="fa-solid fa-trash-can"></i></span><h3 id="ccTitle">Clear cart?</h3><p>This will remove all items from your cart. This action cannot be undone.</p>
    <div class="cc-actions"><button type="button" class="cc-cancel" data-cc="close">Cancel</button><button type="button" class="cc-confirm" data-cc="ok"><i class="fa-solid fa-trash-can"></i> Clear Cart</button></div></div>`;
  document.body.appendChild(wrap);
  requestAnimationFrame(() => wrap.classList.add("open"));
  const close = () => { wrap.classList.remove("open"); setTimeout(() => wrap.remove(), 180); };
  wrap.addEventListener("click", async (e) => {
    if (e.target === wrap || e.target.closest('[data-cc="close"]')) return close();
    const ok = e.target.closest('[data-cc="ok"]');
    if (!ok) return;
    ok.disabled = true;
    const { error } = await sb.from("cart_items").delete().eq("buyer_id", session.user.id);
    if (error) { ok.disabled = false; showToast(error.message || "Couldn't clear your cart.", "error"); return; }
    close();
    showToast("Cart cleared.", "success");
    try { updateCartFab(); } catch (_) {}
    refreshNotifications();
    navigate("cart", {}, false);
  });
}
async function addToCart(productId, qty, variantId = null) {
  if (!session) { showLogin(); return; }
  if (blockOwnVendorPurchase(currentProductDetail?.vendor?.id, "buy")) return;
  const amount = Math.max(1, Number(qty) || 1);
  const chosenVariantId = variantId || byId("selectedProductVariantId")?.value || null;
  // Buyers are no longer blocked by a stock counter here -- see
  // create_sale_order's own comment for why. The vendor is better placed
  // than a raw number to say an order can't be fulfilled.
  const { error } = await sb.rpc("add_to_cart", { p_product_id: productId, p_quantity: amount, p_variant_id: chosenVariantId });
  if (error) { showToast(error.message, "error"); return; }
  showToast("Added to cart.", "success");
  buyerCartCount += 1;
  updateCartFab();
  window.lmSyncCartCount && window.lmSyncCartCount();
  refreshNotifications();
  // Stay on the current page so customers can keep adding multiple items.
  updateCartFab();
}
// One-tap add straight from a product card's grid/rail listing, without
// opening the product page first -- same RPC as addToCart, just with a
// quick icon flip on the button itself as feedback instead of only a toast.
async function quickAddToCart(evt, productId, btn, vendorId = "") {
  evt.stopPropagation();
  if (evt.preventDefault) evt.preventDefault();
  if (!session) { showLogin(); return; }
  if (blockOwnVendorPurchase(vendorId, "buy")) return;
  if (btn.__lmBusy) return;
  btn.__lmBusy = true;
  try { btn.blur(); } catch (_) {}
  const original = btn.dataset.lmOrig || (btn.dataset.lmOrig = btn.innerHTML);
  // Optimistic: the tick and the header badge change on tap, not after the round trip.
  btn.innerHTML = `<i class="fa-solid fa-check"></i>`;
  btn.classList.add("added");
  buyerCartCount += 1;
  updateCartFab();
  const { error } = await sb.rpc("add_to_cart", { p_product_id: productId, p_quantity: 1, p_variant_id: null });
  btn.__lmBusy = false;
  if (error) {
    buyerCartCount = Math.max(0, buyerCartCount - 1);
    updateCartFab();
    btn.innerHTML = original;
    btn.classList.remove("added");
    showToast(error.message, "error");
    return;
  }
  setTimeout(() => { btn.innerHTML = original; btn.classList.remove("added"); }, 900);
  window.lmSyncCartCount && window.lmSyncCartCount();
}
async function updateCartQty(cartItemId, newQty) {
  if (newQty < 1) return;
  const { error } = await sb.from("cart_items").update({ quantity: newQty }).eq("id", cartItemId);
  if (error) { showToast(error.message, "error"); return; }
  navigate("cart", {}, false);
  refreshNotifications();
}
async function removeFromCart(cartItemId) {
  const { error } = await sb.from("cart_items").delete().eq("id", cartItemId);
  if (error) { showToast(error.message, "error"); return; }
  navigate("cart", {}, false);
  refreshNotifications();
}
async function clearStaleCartItems() {
  const ids = window.__staleCartIds || [];
  if (!ids.length) return;
  await sb.from("cart_items").delete().in("id", ids);
  navigate("cart", {}, false);
}
function openCheckoutAllSheet() {
  if (byId("checkoutAllSheet")) return;
  const n = (window.__cartByVendor && window.__cartByVendor.size) || 0;
  if (!n) { showToast("Your cart is empty.", "error"); return; }
  const wrap = document.createElement("div");
  wrap.id = "checkoutAllSheet";
  wrap.className = "cc-backdrop";
  wrap.innerHTML = `<div class="cc-sheet" role="dialog" aria-modal="true" aria-labelledby="coaTitle"><button type="button" class="cc-x" aria-label="Close" data-cc="close"><i class="fa-solid fa-xmark"></i></button>
    <span class="cc-ico coa-ico"><i class="fa-solid fa-bag-shopping"></i></span><h3 id="coaTitle">Checkout everything?</h3><p>This places ${n} order${n === 1 ? "" : "s"}, one per vendor in your cart. You'll see the full breakdown and total before anything is sent.</p>
    <div class="cc-actions"><button type="button" class="cc-cancel" data-cc="close">Cancel</button><button type="button" class="cc-confirm coa-ok" data-cc="ok"><i class="fa-solid fa-bag-shopping"></i> Checkout all</button></div></div>`;
  document.body.appendChild(wrap);
  requestAnimationFrame(() => wrap.classList.add("open"));
  const close = () => { wrap.classList.remove("open"); setTimeout(() => wrap.remove(), 180); };
  wrap.addEventListener("click", (e) => {
    if (e.target === wrap || e.target.closest('[data-cc="close"]')) return close();
    if (e.target.closest('[data-cc="ok"]')) { close(); checkoutCartAll(); }
  });
}
async function checkoutCartAll() {
  const groups = [...(window.__cartByVendor || new Map()).entries()].filter(([id]) => !isOwnVendorId(id));
  if (!groups.length) { showToast("Your cart is empty.", "error"); return; }
  const plan = [];
  for (const [vendorId, group] of groups) {
    const errorEl = byId(`cartError-${vendorId}`);
    errorEl?.classList.add("hidden");
    const delivery = readDeliveryFields(`cart-${vendorId}`, errorEl);
    if (!delivery) {
      document.querySelector(`[data-cart-vendor="${vendorId}"]`)?.scrollIntoView({ behavior: "smooth", block: "center" });
      const msg = (errorEl?.textContent || "").trim();
      showToast(`${group.vendor.business_name}: ${msg || "Please complete your delivery details."}`, "error");
      return;
    }
    let itemsTotal = 0;
    const lines = group.items.map((it) => {
      const unit = Number(effectivePrice(it.variant && it.variant.sale_price != null ? it.variant : it.product) ?? 0);
      itemsTotal += unit * it.quantity;
      return `${it.quantity}× ${it.product.name}${it.variant?.name ? ` (${it.variant.name})` : ""} · ${naira(unit * it.quantity)}`;
    });
    const { fee, known } = computeDeliveryFeeForPrefix(`cart-${vendorId}`, delivery.method);
    plan.push({ vendorId, group, delivery, lines, itemsTotal, fee: known ? Number(fee) || 0 : 0, known });
  }
  const grand = plan.reduce((n, p) => n + p.itemsTotal + p.fee, 0);
  const anyUnknown = plan.some((p) => !p.known && p.delivery.method === "delivery");
  const confirmHtml = plan.map((p) => `<div style="margin:0 0 .7rem;"><strong>${esc(p.group.vendor.business_name)}</strong>` + orderSummaryConfirmHtml({ itemLines: p.lines, method: p.delivery.method, pickupLabel: "Pickup", deliveryFee: p.fee, feeKnown: p.known, itemTotal: p.itemsTotal }) + `</div>`).join("") +
    `<div style="display:flex;justify-content:space-between;font-weight:800;border-top:1px solid var(--border,#e5e7eb);padding-top:.6rem;"><span>Total (${plan.length} order${plan.length === 1 ? "" : "s"})</span><span>${naira(grand)}${anyUnknown ? "+" : ""}</span></div>`;
  if (!(await showConfirmDialog(confirmHtml, { title: "Confirm checkout of everything", okLabel: "Checkout all", html: true }))) return;
  let done = 0, lastId = null, failed = [];
  for (const p of plan) {
    try {
      const { data: orderId, error } = await sb.rpc("create_cart_order", {
        p_vendor_id: p.vendorId,
        p_items: p.group.items.map((it) => ({ product_id: it.product.id, quantity: it.quantity, variant_id: it.variant?.id || null })),
        p_delivery_method: p.delivery.method, p_delivery_address: p.delivery.address, p_delivery_phone: p.delivery.phone,
        p_buyer_note: byId(`cartNote-${p.vendorId}`)?.value.trim() || null,
        p_buyer_lat: buyerLocation?.lat ?? null, p_buyer_lng: buyerLocation?.lng ?? null,
      });
      if (error) throw error;
      await sb.from("cart_items").delete().in("id", p.group.items.map((it) => it.id));
      await persistBuyerDeliveryLocation(orderId, p.delivery.method);
      done++; lastId = orderId;
    } catch (e) { failed.push(`${p.group.vendor.business_name}: ${e.message || "failed"}`); }
  }
  refreshNotifications();
  if (failed.length) showToast(`${done} placed. Couldn't place: ${failed.join("; ")}`, "error");
  if (done === 1 && !failed.length) navigate("orderDetail", { orderId: lastId });
  else if (done) { if (!failed.length) showToast(`${done} orders placed`, "success"); navigate(failed.length ? "cart" : "buyerOrders", {}, false); }
}

async function checkoutCartVendor(vendorId) {
  vendorId = String(vendorId);
  if (blockOwnVendorPurchase(vendorId, "buy")) return;
  const group = window.__cartByVendor?.get(vendorId);
  const errorEl = byId(`cartError-${vendorId}`);
  if (!group) { showToast("Your cart has changed. Reopen the cart and try again.", "error"); return; }
  try {
  errorEl?.classList.add("hidden");
  const delivery = readDeliveryFields(`cart-${vendorId}`, errorEl);
  if (!delivery) return;

  const items = group.items.map((it) => ({ product_id: it.product.id, quantity: it.quantity, variant_id: it.variant?.id || null }));
  // Same itemised breakdown the product page shows: each item, the delivery fee and the real total.
  let cartItemsTotal = 0;
  const cartLines = group.items.map((it) => {
    const unit = Number(effectivePrice(it.variant && it.variant.sale_price != null ? it.variant : it.product) ?? 0);
    cartItemsTotal += unit * it.quantity;
    return `${it.quantity}× ${it.product.name}${it.variant?.name ? ` (${it.variant.name})` : ""} · ${naira(unit * it.quantity)}`;
  });
  const { fee: cartFee, known: cartFeeKnown } = computeDeliveryFeeForPrefix(`cart-${vendorId}`, delivery.method);
  const confirmHtml = `<p style="margin:0 0 .6rem;">${esc(group.vendor.business_name)}</p>` + orderSummaryConfirmHtml({ itemLines: cartLines, method: delivery.method, pickupLabel: "Pickup", deliveryFee: cartFee, feeKnown: cartFeeKnown, itemTotal: cartItemsTotal });
  if (!(await showConfirmDialog(confirmHtml, { title: "Confirm checkout", okLabel: "Checkout", html: true }))) return;

  const { data: orderId, error } = await sb.rpc("create_cart_order", {
    p_vendor_id: vendorId,
    p_items: items,
    p_delivery_method: delivery.method,
    p_delivery_address: delivery.address,
    p_delivery_phone: delivery.phone,
    p_buyer_note: byId(`cartNote-${vendorId}`)?.value.trim() || null,
    p_buyer_lat: buyerLocation?.lat ?? null,
    p_buyer_lng: buyerLocation?.lng ?? null,
  });
  if (error) {
    if (errorEl) { errorEl.textContent = error.message; errorEl.classList.remove("hidden"); }
    return;
  }
  await sb.from("cart_items").delete().in("id", group.items.map((it) => it.id));
  await persistBuyerDeliveryLocation(orderId, delivery.method);
  refreshNotifications();
  navigate("orderDetail", { orderId });
  } catch (err) {
    console.error("Cart checkout failed", err);
    if (errorEl) { errorEl.textContent = "Checkout couldn’t complete. Please try again."; errorEl.classList.remove("hidden"); }
    else showToast("Checkout couldn’t complete. Please try again.", "error");
  }
}

// ---------- IN-APP MESSAGING ----------
// One continuous text thread per (buyer, vendor) pair - replaces direct
// WhatsApp contact so conversations stay evidence-grade for disputes
// (messages can't be edited or deleted, enforced server-side, not just in
// this UI). Customers open a thread from a product/storefront page; vendors
// see all their threads from a "Messages" nav entry.
let activeMsgChannel = null;
let activeConversationId = null;
// Last-seen messages per conversation, kept only in memory for this tab.
// Lets a re-opened DM paint its previous messages immediately (see the
// fast-path in navigate()) instead of a spinner while the fresh fetch is
// still in flight underneath.
const lastSeenMessagesByConv = new Map();

async function callVendorFromOrder(vendorId) {
  if (!session) { showLogin(); return; }
  try {
    const { data: conversationId, error } = await sb.rpc("get_or_create_conversation", { p_vendor_id: vendorId });
    if (error) throw error;
    await window.startVoiceCall(conversationId);
  } catch (e) { showToast(e.message || "Couldn't start the call.", "error"); }
}
async function callCustomerFromOrder(orderId) {
  if (!session) { showLogin(); return; }
  try {
    const { data: order, error } = await sb.from("orders").select("id,buyer_id,vendor_id").eq("id", orderId).maybeSingle();
    if (error || !order) throw error || new Error("Order not found.");
    const { data: existing } = await sb.from("conversations").select("id").eq("buyer_id", order.buyer_id).eq("vendor_id", order.vendor_id).maybeSingle();
    let conversationId = existing?.id;
    if (!conversationId) {
      const { data: created, error: createErr } = await sb.from("conversations").insert({ buyer_id: order.buyer_id, vendor_id: order.vendor_id }).select("id").single();
      if (createErr) throw createErr;
      conversationId = created.id;
    }
    await window.startVoiceCall(conversationId);
  } catch (e) { showToast(e.message || "Couldn't start the call.", "error"); }
}
async function startConversationWithVendor(vendorId, draftText) {
  if (!session) { showLogin(); return; }
  const { data: v } = await sb.from("vendors").select("business_name, business_hours, allow_after_hours_messages").eq("id", vendorId).maybeSingle();
  if (v && !canMessageVendorNow(v)) {
    const status = vendorHoursStatus(v);
    showToast(`${v.business_name || "This vendor"} is outside working hours right now${status.todayText ? ` (${status.todayLabel}: ${status.todayText})` : ""}. Try again during their working hours.`, "info");
    return;
  }
  if (!(await ensureCustomerProfile())) {
    showToast("Your account profile could not be repaired. Please refresh the app and try again.", "error");
    return;
  }
  let { data: conversationId, error } = await sb.rpc("get_or_create_conversation", { p_vendor_id: vendorId });
  if (error && /foreign key|buyer_id|vendor_id/i.test(error.message || "")) {
    // One final repair/retry handles a race where the profile was created just
    // after the first existence check.
    buyerProfileRepairPromise = null;
    if (await ensureCustomerProfile()) {
      ({ data: conversationId, error } = await sb.rpc("get_or_create_conversation", { p_vendor_id: vendorId }));
    }
  }
  if (error) { showToast(/once you have placed an order/i.test(error.message || "") ? error.message : "We couldn't start this conversation. Please try again.", /once you have placed an order/i.test(error.message || "") ? "info" : "error"); return; }
  await navigate("messages", { conversationId });
  if (draftText) {
    const input = byId("chatInput");
    if (input) { input.value = draftText; autoGrowChatInput(input); input.focus(); }
  }
}

// ---------- SUGGESTION BOX ----------
// Free-form feedback, either to Levromart itself or to a specific vendor,
// with an optional anonymous toggle enforced at read time (see
// get_platform_suggestions/get_vendor_suggestions) so the recipient never
// sees who sent an anonymous one.
let suggestionTarget = { type: "platform", vendorId: null };
