async function hydratePackageCommentCountsInView(){const ids=[...new Set([...document.querySelectorAll(".package-card-comment-btn[data-package-id],#packageCommentsCount[data-package-id],.package-listing-card[data-package-id]")].map(n=>n.dataset.packageId).filter(Boolean))];if(!ids.length)return;try{const [{data:cc,error},{data:fc},{data:settings}]=await Promise.all([sb.rpc("get_package_comment_counts",{p_package_ids:ids}),sb.rpc("get_package_favorite_counts",{p_package_ids:ids}),sb.from("package_engagement_settings").select("package_id,vendor_id,like_visibility").in("package_id",ids)]);if(!error)(cc||[]).forEach(r=>window.__packageCommentCounts.set(String(r.package_id),Number(r.comment_count||0)));const fm=new Map((fc||[]).map(r=>[String(r.package_id),Number(r.favorite_count||0)]));const sm=new Map((settings||[]).map(r=>[String(r.package_id),r]));document.querySelectorAll(".package-listing-card[data-package-id]").forEach(card=>{const id=String(card.dataset.packageId),st=sm.get(id)||{},e=card.querySelector(".package-like-count"),wrap=e?.closest(".package-card-engagement-count"),visible=st.like_visibility!=="no_one";if(e)e.textContent=String(fm.get(id)||0);wrap?.classList.toggle("hidden",!visible)});}catch(_){}document.querySelectorAll(".package-card-comment-btn[data-package-id]").forEach(b=>{const e=b.querySelector(".package-comment-count");if(e)e.textContent=String(window.__packageCommentCounts.get(String(b.dataset.packageId))||0)})}
// Products didn't have their own rating before -- only the vendor's overall
// rating showed anywhere. product_rating_stats aggregates each product's own
// reviews (via its order history); this patches the placeholder every card
// already renders with the real stars/count once it arrives.
window.__productRatingCache = window.__productRatingCache || new Map();
function productRatingBadgeInnerHtml(stats) {
  if (!stats || !stats.review_count) return `<span class="product-card-rating-empty">${"☆".repeat(5)}</span>`;
  const rounded = Math.round(Number(stats.avg_rating));
  return `<span class="product-card-rating-stars">${"★".repeat(rounded)}${"☆".repeat(5 - rounded)}</span> <span class="product-card-rating-count">(${stats.review_count})</span>`;
}
async function hydrateProductRatingsInView(){
  const ids=[...new Set([...document.querySelectorAll("[data-product-rating-id]")].map(n=>n.dataset.productRatingId).filter(Boolean))];
  if(!ids.length)return;
  const uncached=ids.filter(id=>!window.__productRatingCache.has(id));
  if(uncached.length){
    try{
      const {data,error}=await sb.from("product_rating_stats").select("product_id,avg_rating,review_count").in("product_id",uncached);
      if(error)throw error;
      const found=new Set();
      (data||[]).forEach(r=>{window.__productRatingCache.set(String(r.product_id),{avg_rating:r.avg_rating,review_count:r.review_count});found.add(String(r.product_id))});
      uncached.forEach(id=>{if(!found.has(id))window.__productRatingCache.set(id,{avg_rating:0,review_count:0})});
    }catch(error){console.warn("[Levromart] Product ratings refresh failed:",error);return}
  }
  document.querySelectorAll("[data-product-rating-id]").forEach(n=>{
    const stats=window.__productRatingCache.get(String(n.dataset.productRatingId));
    if(stats)n.innerHTML=productRatingBadgeInnerHtml(stats);
  });
}
async function hydrateProductLikeCountsInView(){const ids=[...new Set([...document.querySelectorAll("[data-product-like-id]")].map(n=>n.dataset.productLikeId).filter(Boolean))];if(!ids.length)return;try{const [{data:counts,error:countError},{data:settings,error:settingsError}]=await Promise.all([sb.rpc("get_favorite_counts",{p_product_ids:ids}),sb.from("product_engagement_settings").select("product_id,vendor_id,like_visibility").in("product_id",ids)]);if(countError||settingsError)throw countError||settingsError;const cm=new Map((counts||[]).map(r=>[String(r.product_id),Number(r.favorite_count??r.count??0)]));const sm=new Map((settings||[]).map(r=>[String(r.product_id),r]));const followed=new Set();const vids=[...(settings||[]).map(r=>r.vendor_id).filter(Boolean)];if(session?.user?.id&&vids.length){const {data:fs}=await sb.from("vendor_follows").select("vendor_id").eq("follower_id",session.user.id).in("vendor_id",[...new Set(vids)]);(fs||[]).forEach(r=>followed.add(String(r.vendor_id)));}document.querySelectorAll("[data-product-like-id]").forEach(n=>{const id=String(n.dataset.productLikeId),st=sm.get(id)||{},visible=st.like_visibility!=="no_one"&&(st.like_visibility!=="followers"||followed.has(String(st.vendor_id))||isOwnVendorId(st.vendor_id));const e=n.querySelector(".product-like-indicator");if(!e)return;if(visible){e.classList.remove("hidden");e.querySelector("span").textContent=String(cm.get(id)||0)}else e.classList.add("hidden")})}catch(error){console.warn("[Levromart] Like counts refresh failed:",error)}
}
