async function fetchProductComments(id){const {data,error}=await sb.from("product_comments").select("id,product_id,user_id,parent_comment_id,content,author_name,author_avatar_url,created_at,updated_at").eq("product_id",id).order("created_at",{ascending:false}).limit(120);if(error)throw error;const rows=data||[];let likes=[];if(rows.length){const r=await sb.from("product_comment_likes").select("id,comment_id,user_id").in("comment_id",rows.map(x=>x.id));if(!r.error)likes=r.data||[]}const lm=new Map(),ml=new Set();likes.forEach(l=>{const k=String(l.comment_id);lm.set(k,(lm.get(k)||0)+1);if(session?.user?.id&&String(l.user_id)===String(session.user.id))ml.add(k)});return{rows,likeMap:lm,myLiked:ml}}
function socialCommentRow(c,lm,ml,d=0,kind="product"){const liked=ml.has(String(c.id)),own=String(session?.user?.id||"")===String(c.user_id||"");const lf=kind==="package"?"togglePackageCommentLike":"toggleProductCommentLike",rf=kind==="package"?"replyToPackageComment":"replyToProductComment",df=kind==="package"?"deletePackageComment":"deleteProductComment";return `<div class="product-comment-row" data-comment-id="${esc(c.id)}" data-depth="${d}">${c.author_avatar_url?`<img src="${esc(c.author_avatar_url)}" class="product-comment-avatar" alt="${esc(c.author_name||"User")}">`:avatarFallbackHtml(c.author_name||"User","2rem","product-comment-avatar",c.author_name||"User",c.user_id||c.author_name)}<div class="product-comment-main"><div class="product-comment-head"><strong>${esc(c.author_name||"Levromart user")}</strong><span class="muted">${timeAgo(c.created_at)}</span>${c.updated_at&&new Date(c.updated_at)-new Date(c.created_at)>3000?'<span class="muted lv-edited">· edited</span>':""}</div><div class="product-comment-body">${esc(c.content)}</div><div class="product-comment-actions"><button type="button" class="product-comment-action ${liked?"active":""}" onclick="${lf}('${esc(c.id)}')" aria-label="Like comment" title="Like comment"><i class="fa-${liked?"solid":"regular"} fa-heart"></i><span class="comment-like-count">${Number(lm.get(String(c.id))||0)}</span></button><button type="button" class="product-comment-action" onclick="${rf}('${esc(c.id)}')" aria-label="Reply to comment" title="Reply"><i class="fa-solid fa-reply"></i></button>${own?`<button type="button" class="product-comment-action lv-cmore" onclick="lvCommentMenu('${kind==="package"?"package":"product"}','${esc(c.id)}')" aria-label="Comment options" title="More"><i class="fa-solid fa-ellipsis"></i></button>`:""}</div></div></div>`}
function socialThread(rows,lm,ml,kind){const roots=rows.filter(r=>!r.parent_comment_id),ch=new Map();rows.filter(r=>r.parent_comment_id).forEach(r=>{const k=String(r.parent_comment_id);if(!ch.has(k))ch.set(k,[]);ch.get(k).push(r)});const render=(p,d=1)=>{const kids=(ch.get(String(p.id))||[]).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));if(!kids.length)return"";const first=kids[0],rest=kids.slice(1),pre=kind==="package"?"packageReplies":"commentReplies";return socialCommentRow(first,lm,ml,d,kind)+(rest.length?`<div class="comment-more-replies"><button type="button" class="comment-view-more" onclick="toggleCommentReplies('${esc(p.id)}','${kind}')"><i class="fa-solid fa-chevron-down"></i> See ${rest.length} more repl${rest.length===1?"y":"ies"}</button><div class="comment-hidden-replies hidden" id="${pre}-${esc(p.id)}">${rest.map(r=>socialCommentRow(r,lm,ml,d,kind)).join("")}</div></div>`:"")+render(first,d+1)+rest.map(r=>render(r,d+1)).join("")};return roots.map(r=>socialCommentRow(r,lm,ml,0,kind)+render(r,1)).join("")}
function toggleCommentReplies(id,kind="product"){const e=byId(`${kind==="package"?"packageReplies":"commentReplies"}-${id}`);if(!e)return;e.classList.toggle("hidden");const b=e.parentElement?.querySelector(".comment-view-more");if(b)b.innerHTML=e.classList.contains("hidden")?`<i class="fa-solid fa-chevron-down"></i> See more replies`:`<i class="fa-solid fa-chevron-up"></i> Hide replies`}
async function loadProductComments(id,{preserveDraft=true,showLoading=true,force=false}={}){const p=activeSocialCommentPanel("product");if(!p)return;const d=preserveDraft?(activeSocialCommentInput("product")?.value||""):"",k=String(id);if(!force&&productCommentsLoaded.has(k)&&!productCommentsFetches.has(k)){renderLoadedProductComments(id,productCommentsLoaded.get(k),d);return}if(productCommentsFetches.has(k))return productCommentsFetches.get(k);const req=(async()=>{try{const r=await fetchProductComments(id);productCommentsLoaded.set(k,r);renderLoadedProductComments(id,r,d)}catch(_){if(!productCommentsLoaded.has(k))p.innerHTML=`<div class="product-comments-empty">Couldn’t load comments right now. Please try again.</div>`}finally{productCommentsFetches.delete(k)}})();productCommentsFetches.set(k,req);return req}
function renderLoadedProductComments(id,r,d=""){const p=activeSocialCommentPanel("product");if(!p)return;window.__productCommentCounts.set(String(id),r.rows.length);byId("productCommentsCount")?.replaceChildren(document.createTextNode(String(r.rows.length)));const thread=r.rows.length?socialThread(r.rows,r.likeMap,r.myLiked,"product"):"<div class=\"product-comments-empty\">No comments yet. Be the first to ask a question.</div>";const av=session?profileAvatarHtml(profile?.avatar_url||"",profile?.name||"You","2rem",{stableKey:session.user.id}):avatarFallbackHtml("You","2rem","product-comment-avatar","You","guest");const composer='<div class="product-comment-composer">'+(activeProductCommentReplyId?'<div class="product-comment-replying">Replying to a comment <button type="button" class="icon-btn" onclick="cancelProductCommentReply()" aria-label="Cancel reply"><i class="fa-solid fa-xmark"></i></button></div>':'')+'<div class="product-comment-compose-row">'+av+'<textarea id="productCommentInput" rows="1" placeholder="Add a comment…" '+(session?'':'disabled')+'>'+esc(d)+'</textarea><button type="button" class="icon-btn" onclick="submitProductComment(\''+esc(id)+'\')" '+(session?'':'disabled')+' aria-label="Send comment"><i class="fa-solid fa-paper-plane"></i></button></div></div>';p.innerHTML='<div class="levro-engagement-strip" id="productEngagementStrip-'+esc(id)+'"><span class="levro-engagement-empty">Loading engagement…</span></div>'+thread+composer;loadCommentEngagementStrip("product",id)}
function ensureProductCommentRealtime(id){if(!id||!sb)return;if(productCommentRealtimeChannel&&productCommentRealtimeProductId===String(id))return;stopProductCommentRealtime();productCommentRealtimeProductId=String(id);productCommentRealtimeChannel=sb.channel(`product-comments-${id}`).on("postgres_changes",{event:"*",schema:"public",table:"product_comments",filter:`product_id=eq.${id}`},async()=>{try{const r=await fetchProductComments(id);productCommentsLoaded.set(String(id),r);renderLoadedProductComments(id,r,activeSocialCommentInput("product")?.value||"");hydrateProductCommentCountsInView()}catch(_){}}).subscribe()}function stopProductCommentRealtime(){if(productCommentRealtimeChannel){try{sb.removeChannel(productCommentRealtimeChannel)}catch(_){}}productCommentRealtimeChannel=null;productCommentRealtimeProductId=null}
function replyToProductComment(id){activeProductCommentReplyId=String(id);activeSocialCommentInput("product")?.focus()}function cancelProductCommentReply(){activeProductCommentReplyId=null;if(currentProductDetail?.id)loadProductComments(currentProductDetail.id,{showLoading:false})}
async function submitProductComment(id){if(!session){showLogin();return}const content=String(activeSocialCommentInput("product")?.value||"").trim();if(!content){showToast("Write a comment first.","error");return}const {data:st}=await sb.from("product_engagement_settings").select("allow_comments,comment_audience,vendor_id").eq("product_id",id).maybeSingle();if(st?.allow_comments===false){showToast("Comments are disabled for this listing.","error");return}if(st?.comment_audience==="followers"&&!isOwnVendorId(st.vendor_id)){const {data:f}=await sb.from("vendor_follows").select("id").eq("vendor_id",st.vendor_id).eq("follower_id",session.user.id).maybeSingle();if(!f){showToast("Only followers can comment on this listing.","error");return}}const {error}=await sb.from("product_comments").insert({product_id:id,user_id:session.user.id,parent_comment_id:activeProductCommentReplyId||null,content,author_name:profile?.name||"Levromart user",author_avatar_url:profile?.avatar_url||null});if(error){showToast(error.message||"Could not post that comment.","error");return}activeProductCommentReplyId=null;await loadProductComments(id,{preserveDraft:false,showLoading:false,force:true})}
async function toggleProductCommentLike(id){if(!session){showLogin();return}const {data:x}=await sb.from("product_comment_likes").select("id").eq("comment_id",id).eq("user_id",session.user.id).maybeSingle();const r=x?.id?await sb.from("product_comment_likes").delete().eq("id",x.id).eq("user_id",session.user.id):await sb.from("product_comment_likes").insert({comment_id:id,user_id:session.user.id});if(r.error&&!/duplicate/i.test(r.error.message||"")){showToast(r.error.message||"Could not update comment like.","error");return}if(currentProductDetail?.id)loadProductComments(currentProductDetail.id,{showLoading:false,force:true})}
async function deleteProductComment(id){if(!session)return;if(!(await showConfirmDialog("Delete your comment?",{title:"Delete comment",okLabel:"Delete",danger:true})))return;const {error}=await sb.from("product_comments").delete().eq("id",id).eq("user_id",session.user.id);if(error){showToast(error.message||"Could not delete comment.","error");return}if(currentProductDetail?.id)loadProductComments(currentProductDetail.id,{showLoading:false,force:true})}
async function fetchPackageComments(id){const {data,error}=await sb.from("package_comments").select("id,package_id,user_id,parent_comment_id,content,author_name,author_avatar_url,created_at,updated_at").eq("package_id",id).order("created_at",{ascending:false}).limit(120);if(error)throw error;const rows=data||[];let likes=[];if(rows.length){const r=await sb.from("package_comment_likes").select("id,comment_id,user_id").in("comment_id",rows.map(x=>x.id));if(!r.error)likes=r.data||[]}const lm=new Map(),ml=new Set();likes.forEach(l=>{const k=String(l.comment_id);lm.set(k,(lm.get(k)||0)+1);if(session?.user?.id&&String(l.user_id)===String(session.user.id))ml.add(k)});return{rows,likeMap:lm,myLiked:ml}}
async function loadPackageComments(id,{preserveDraft=true,showLoading=true,force=false}={}){const p=activeSocialCommentPanel("package");if(!p)return;const d=preserveDraft?(activeSocialCommentInput("package")?.value||""):"",k=String(id);if(!force&&packageCommentsLoaded.has(k)&&!packageCommentsFetches.has(k)){renderLoadedPackageComments(id,packageCommentsLoaded.get(k),d);return}if(packageCommentsFetches.has(k))return packageCommentsFetches.get(k);const req=(async()=>{try{const r=await fetchPackageComments(id);packageCommentsLoaded.set(k,r);renderLoadedPackageComments(id,r,d)}catch(_){if(!packageCommentsLoaded.has(k))p.innerHTML=`<div class="product-comments-empty">Couldn’t load comments right now. Please try again.</div>`}finally{packageCommentsFetches.delete(k)}})();packageCommentsFetches.set(k,req);return req}
function renderLoadedPackageComments(id,r,d=""){const p=activeSocialCommentPanel("package");if(!p)return;window.__packageCommentCounts.set(String(id),r.rows.length);byId("packageCommentsCount")?.replaceChildren(document.createTextNode(String(r.rows.length)));const thread=r.rows.length?socialThread(r.rows,r.likeMap,r.myLiked,"package"):"<div class=\"product-comments-empty\">No comments yet. Be the first to ask a question.</div>";const av=session?profileAvatarHtml(profile?.avatar_url||"",profile?.name||"You","2rem",{stableKey:session.user.id}):avatarFallbackHtml("You","2rem","product-comment-avatar","You","guest");const composer='<div class="product-comment-composer">'+(activePackageCommentReplyId?'<div class="product-comment-replying">Replying to a comment <button type="button" class="icon-btn" onclick="cancelPackageCommentReply()" aria-label="Cancel reply"><i class="fa-solid fa-xmark"></i></button></div>':'')+'<div class="product-comment-compose-row">'+av+'<textarea id="packageCommentInput" rows="1" placeholder="Add a comment…" '+(session?'':'disabled')+'>'+esc(d)+'</textarea><button type="button" class="icon-btn" onclick="submitPackageComment(\''+esc(id)+'\')" '+(session?'':'disabled')+' aria-label="Send comment"><i class="fa-solid fa-paper-plane"></i></button></div></div>';p.innerHTML='<div class="levro-engagement-strip" id="packageEngagementStrip-'+esc(id)+'"><span class="levro-engagement-empty">Loading engagement…</span></div>'+thread+composer;loadCommentEngagementStrip("package",id)}
function ensurePackageCommentRealtime(id){if(!id||!sb)return;if(packageCommentRealtimeChannel&&packageCommentRealtimePackageId===String(id))return;stopPackageCommentRealtime();packageCommentRealtimePackageId=String(id);packageCommentRealtimeChannel=sb.channel(`package-comments-${id}`).on("postgres_changes",{event:"*",schema:"public",table:"package_comments",filter:`package_id=eq.${id}`},async()=>{try{const r=await fetchPackageComments(id);packageCommentsLoaded.set(String(id),r);renderLoadedPackageComments(id,r,activeSocialCommentInput("package")?.value||"");hydratePackageCommentCountsInView()}catch(_){}}).subscribe()}function stopPackageCommentRealtime(){if(packageCommentRealtimeChannel){try{sb.removeChannel(packageCommentRealtimeChannel)}catch(_){}}packageCommentRealtimeChannel=null;packageCommentRealtimePackageId=null}
