async function submitPackageComment(id){if(!session){showLogin();return}const content=String(activeSocialCommentInput("package")?.value||"").trim();if(!content){showToast("Write a comment first.","error");return}const {data:st}=await sb.from("package_engagement_settings").select("allow_comments,comment_audience,vendor_id").eq("package_id",id).maybeSingle();if(st?.allow_comments===false){showToast("Comments are disabled for this package.","error");return}if(st?.comment_audience==="followers"&&!isOwnVendorId(st.vendor_id)){const {data:f}=await sb.from("vendor_follows").select("id").eq("vendor_id",st.vendor_id).eq("follower_id",session.user.id).maybeSingle();if(!f){showToast("Only followers can comment on this package.","error");return}}const {error}=await sb.from("package_comments").insert({package_id:id,user_id:session.user.id,parent_comment_id:activePackageCommentReplyId||null,content,author_name:profile?.name||"Levromart user",author_avatar_url:profile?.avatar_url||null});if(error){showToast(error.message||"Could not post that comment.","error");return}activePackageCommentReplyId=null;await loadPackageComments(id,{preserveDraft:false,showLoading:false,force:true})}
